quests[13156] = { id = 13156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rare Herb", description = "My, it its quite chilly up here! Reminds me of the stormy peaks of Kaarinos on Argus. However, with all of this snow and ice, our soldiers can easily catch cold.\n\nHead to the Steppe of Life in southwestern Wintergrasp, and bring me back 10 of the Horde herb pouches you find. I will grind them into a medicine to help protect against the cold.\n\nThe Horde have been seen collecting them from the plant life in the area. Do not hesitate to slay them and retrieve the herbs!", sourceObjective = "Anchorite Tessa in Wintergrasp Fortress wants you to retrieve 10 Horde Herb Pouches from Horde players in the Steppe of Life.", progress = "I hope you didn't pull up any of the lashers by mistake! They gave Private Doane quite a whipping last week.", completion = "Excellent! This will help protect our troops against the cold.", sourceObjectiveStatus = "unverified-source-field" }
quests[13157] = { id = 13157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crusaders' Pinnacle", description = "Stand proud in knowing that it was you who helped establish the Argent Crusade inside the walls of Icecrown, {name}. The Crusaders' Pinnacle now stands in direct defiance of the Lich King and his twisted minions.\n\nHighlord Fordring and the crusaders who survived await your arrival at Crusaders' Pinnacle. Travel once more through the Breach and seek out the highlord!", sourceObjective = "Seek out Highlord Tirion Fordring at Crusaders' Pinnacle in Icecrown.", completion = "A long and arduous journey awaits us as we make our way to the gates of Icecrown Citadel. I, and the soldiers of the Argent Crusade, wish to thank you for all that you have done. We rest easier knowing that you will fight alongside us in this cursed place.\n\n<Highlord Tirion Fordring salutes.>", sourceObjectiveStatus = "unverified-source-field" }
quests[13158] = { id = 13158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discretion is Key", description = "Listen to me, {race}.\n\nIt's just been brought to my attention that there's been an incident at the Violet Hold. It would appear that the blues are launching a full scale invasion of Dalaran!\n\nI need you to get to the prison and speak with Warden Alturas at once. He'll give you the details.\n\nThat is not all. I need this handled with utmost discretion. We mustn't alarm the citizens of Dalaran if it can possibly be avoided. Do I make myself clear?\n\nVery well. Now, go!", sourceObjective = "Rhonin wants you to go to the Violet Hold in Dalaran and speak with Warden Alturas.", completion = "Not a moment too soon.\n\nAre you prepared to defend Dalaran, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[13159] = { id = 13159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Containment", description = "Here is the prison key.\n\nMy men and I will stay here as a last line of defense in the event that you are unable to overcome the assault.\n\nBe sure to speak with Lieutenant Sinclari. She'll provide you with access to the prison's defenses.\n\nHurry, {race}. There is little time. The few I left inside won't last long without your help. Report back to me once the invasion forces have been successfully dealt with.", sourceObjective = "Warden Alturas wants you to enter the Violet Hold and put an end to the blue dragon invasion force. You are to report back to him once Cyanigosa is slain.", progress = "Is it over? Were you able to withstand the assault?", completion = "The crisis is averted, then?\n\nThat is good news indeed. I will forward the news on to Rhonin.\n\nPlease, accept this with the gratitude of Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[13160] = { id = 13160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stunning View", description = "Gargoyles make effective scouts and can be deadly if left to rain attacks from the air, but they have a very obvious weakness. Most of them have to go through long periods resting as stone to maintain the energy they need to carry their heavy bodies through the air.\n\nAs I peered through the eye you were using, I noticed dozens of iceskin sentries resting on the eastern and southern walls inside. Use the stalker to leap up to their ledges and devastate them while they sleep.", sourceObjective = "Vereth the Cunning at the Rise of Suffering wants you to use a Lithe Stalker's heave ability to destroy 12 sleeping Iceskin Sentries.", progress = "Almost too easy.", completion = "Not so much of a threat when they're sleeping.", sourceObjectiveStatus = "unverified-source-field" }
quests[13161] = { id = 13161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rider of the Unholy", description = "It's time that we start cutting off the heads of the beast.\n\nI served beside Rokir for quite some time. He knows the unholy arts better than most any other death knight I've met and he's equally as ruthless.\n\nRokir's strengths are most apparent when you are fighting him on his own ground. Sadly, we don't have much option in those regards, but stay on your feet to avoid his undead minions and you should come out victorious.\n\nBe nimble, {class}, and do not take him lightly.", sourceObjective = "Vereth the Cunning on the Rise of Suffering wants you to kill Rokir, the Rider of the Unholy.", progress = "Is it done?", completion = "The world will be a much better place without Rokir in it - trust me.", sourceObjectiveStatus = "unverified-source-field" }
quests[13162] = { id = 13162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rider of Frost", description = "Sapph... Sapph's a death knight like no other. She'll shower you with sweet words and you'll swear that she has no evil within her heart, and then she'll run you through without even breaking her smile.\n\nI have no fear that you'll be able to best Sapph, but do not grow overconfident. Her strength lies in lulling her victims into a false ease, shortly before shattering them with a fierce barrage of frost attacks.\n\nDo not let your guard down, and do not underestimate her.", sourceObjective = "Vereth the Cunning on the Rise of Suffering wants you to kill Sapph, the Rider of Frost.", completion = "I can't deny, I'll miss her laugh... and that smile that would creep onto her face just before she killed someone. A little less need to watch my back though, so I suppose I can't complain.", sourceObjectiveStatus = "unverified-source-field" }
quests[13163] = { id = 13163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rider of Blood", description = "Baelok is one of the few vrykul that I've ever seen rise through the ranks, and that was mostly accomplished through sheer brutality. If your competition ends up dead, there's far less to compete against.\n\nWhen you join battle with him, spread out from your companions and keep your distance as much as you reasonably can. He will not hesitate to steal your life force for himself, so you will need to hinder his ability to do so as much as possible.\n\nYou have my confidence. See to it that he dies.", sourceObjective = "Vereth the Cunning on the Rise of Suffering wants you to kill Baelok, the Rider of Blood.", progress = "Is he dead?", completion = "So he finally lost? Good to hear.", sourceObjectiveStatus = "unverified-source-field" }
quests[13164] = { id = 13164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Bloodbane", description = "With the riders of the Host of Suffering dead, now is the time to put an end to their true leader: Orbaz Bloodbane.\n\nMograine caught up with me while you were off and told me that he found where Orbaz is hiding. Under Icecrown Citadel itself, there is an immense pit - you will find Orbaz just outside its lip.\n\nSome of the Ebon Blade's strongest agents have already been dispatched - gather aid and join the fight. It is time for Bloodbane to die.", sourceObjective = "Vereth on the Rise of Suffering has dispatched you to kill Orbaz Bloodbane.", completion = "Mograine himself arrived to see the deed done then? I imagine there was some ill blood between those two - no surprise that he wanted a piece of the wretch.\n\nYou've done exceedingly well, {race}, and you shall be awarded appropriately. The Ebon Blade thanks you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13165] = { id = 13165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Back Acherus", description = "The haze has been lifted. I can see as clearly now as the day that I plunged the Ashbringer into my own heart to free my father's cursed soul: my last memory as a free man.\n\nWe must take back Acherus from the Scourge if our order is to survive in this new world. I have taught you how to call forth a death gate. The death gate will return you to Acherus when you call upon it, {name}. Use it now and meet me at Acherus. The first battle of the Knights of the Ebon Blade is underway! Death to the Scourge!", sourceObjective = "Use your Death Gate spell to return to Acherus: The Ebon Hold. Report to Highlord Darion Mograine once you arrive.", completion = "The Lich King has returned to Northrend, wounded by the Ashbringer, but the second floor still holds the last of his armies.", sourceObjectiveStatus = "unverified-source-field" }
quests[13166] = { id = 13166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle For The Ebon Hold", description = "The Hall of Command has been secured, but the Lich King has left us a little present in the Heart of Acherus. The stitched terror, Patchwerk, and a horde of abominations have taken over the second floor.\n\nUse the teleporter to get to the second floor and destroy the Scourge forces that remain. Do not engage Patchwerk alone! You must fight the monstrosity with other death knights of Acherus!\n\nGo, {name}. You have my strength to carry you!", sourceObjective = "Slay 10 Scourge and help kill Patchwerk. Return to Highlord Darion Mograine should you succeed.", progress = "Acherus will be ours!", completion = "Well done, {class}. The remaining Scourge will be dealt with in short order and the rebuilding process will begin anew.\n\nI have but one last task for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13167] = { id = 13167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to the Traitor King", description = "Anub'arak, the traitor king, makes his home in the once proud underland of Azjol-Nerub.\n\nSince his betrayal, he has twisted and perverted our homeland into the wretched squalor it is today. He rules over an army of undead nerubians who, like their leader, have pledged themselves to serving the Lich King.\n\nBring an end to the traitor king's reign, {class}. You will be doing a great service to both of our peoples.\n\nIf you manage to succeed where all others have failed, bring me the husk of Anub'arak.", sourceObjective = "Kilix the Unraveler in the Pit of Narjun has tasked you with defeating Anub'arak in Azjol-Nerub. You are to return to Kilix with Anub'arak's Broken Husk.", progress = "Is it done, {class}? Has the traitor king finally met his end?", completion = "<A fierce glow emanantes from all of Kilix's eyes as he stares at the husk.>\n\nIt is DONE!\n\n{race}! Your name shall be recorded in the history of our people.\n\nI am in your debt....", sourceObjectiveStatus = "unverified-source-field" }
quests[13168] = { id = 13168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parting Gifts", description = "Look what we have here... eyes of dominion. The Cult normally goes to great lengths to keep these things safe, but I suppose their options for retreat are few when we're slaughtering them in their own home.\n\nThe eyes allow a being of any relative power to control an undead minion's actions precisely. As you can imagine, this can be extremely useful when it comes to your typical clumsy ghoul or skeleton.\n\nCare to try your hand at it? Use one of the eyes to control a captured shade.", sourceObjective = "Keritose Bloodblade at the Shadow Vault wants you to use an Eye of Dominion to take control of a captured Eidolon Watcher.", progress = "The options of subterfuge made available to us with the eyes are obvious. These will be very useful tools.", completion = "Nothing to it, eh? Any intelligent being should have little trouble controlling lesser undead. I suspect only the likes of a true necromancer could use these to seize control of any of the more powerful undead. That won't be a problem though - I can already think of quite a variety of destruction we can wreak with even the most paltry minions.\n\nShall we have at it then?", sourceObjectiveStatus = "unverified-source-field" }
quests[13169] = { id = 13169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Undead's Best Friend", description = "As is usual practice, the undead at the saronite quarry to the southwest starve plaguehounds to keep them extra aggressive. Use the shade to get up close and feed some of those hounds and I promise you they'll be content to leave you alone, if not side with the hand that fed them.\n\nDon't get too close to those things until you've fed them though. Their noses don't fall victim to your shade's elusiveness.", sourceObjective = "Keritose Bloodblade at the Shadow Vault wants you to use the Eidolon Watcher to feed 18 Hungering Plaguehounds.", progress = "No need to be wasteful - those hounds will serve whoever bothers to feed them.", completion = "Put them right to sleep, didn't it?", sourceObjectiveStatus = "unverified-source-field" }
quests[13170] = { id = 13170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor is for the Weak", description = "Ghouls are fragile things when it comes down to it, and the lookouts at the saronite quarry down the path to the southwest are no exception. Using one of the shades, I have no doubt that you can sneak up and put down their lookouts without making a sound.\n\nClear out as many lookouts as you can reach in a reasonable amount of time... we'll want their ranks thinned for our assault to come.", sourceObjective = "Keritose Bloodblade at the Shadow Vault would like you to assassinate 20 Restless Lookouts.", completion = "Without even getting your hands dirty.", sourceObjectiveStatus = "unverified-source-field" }
quests[13171] = { id = 13171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From Whence They Came", description = "My main concern is the saronite quarry down the path to the southwest. They are pulling up immense amounts of ore from that quarry and I'd like to know what they're building with it. To that end, we'll start by weakening their defenses.\n\nI noticed a series of crystals scattered throughout the base and I assume they are defensive structures of some sort, not unlike ziggurats. Use the eidolon watcher to destroy any of those crystals that you find.", sourceObjective = "Keritose Bloodblade at the Shadow Vault has sent you to banish 10 Scourge Containment Crystals.", progress = "Are those crystals out of the way? I don't want them to prove a nasty surprise for my gryphons.", completion = "Excellent work. We should have little threat in the air then.", sourceObjectiveStatus = "unverified-source-field" }
quests[13172] = { id = 13172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeds of Chaos", description = "Effective tool, is it not? Excellent job weakening their defenses, {class}. Now we can push the main assault.\n\nThe plan here is straight-foward - we're looking to destroy anything moving, and get in there and steal some information amidst the confusion.\n\nLet me know when you're ready and I'll set you up with a skeletal gryphon.", sourceObjective = "Keritose Bloodblade at the Shadow Vault has dispatched you to slaughter 80 undead in the Weeping Quarry. Speak to him to secure a skeletal gryphon for the assault.", completion = "Practically defenseless. It doesn't get much easier than that.", sourceObjectiveStatus = "unverified-source-field" }
quests[13173] = { id = 13173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amidst the Confusion", description = "We got our hands on quite a few workers. They should do nicely.\n\nI want you to use an eye to bring one of these workers back into the quarry. With the entire camp in disarray, there's no way they'll be able to distinguish you from any of the other workers that were scattered by the assault.\n\nFind whoever is in charge of the operation and get to work. With any luck, we'll find out where that Saronite is being shipped off to pretty quickly. I'll watch over your shoulder through the eye." }
quests[13174] = { id = 13174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amidst the Confusion", description = "Shutting down their operation is just half of the plan. The other important goal here is to find out where all that saronite is being sent. We know of a few places it's been ending up, but the amount they're pulling out suggests to me that there's a bigger project in the works.\n\nOnce you're inside the quarry, get your hands on any of their documents that you can find. If you're assaulting the place with one of the gryphons, you can drop down from it as soon as the wetwork is done.", sourceObjective = "Keritose Bloodblade at the Shadow Vault has requested a Weeping Quarry Document, a Weeping Quarry Ledger, a Weeping Quarry Map, and a Weeping Quarry Schedule.", progress = "Did you bring back what I requested?", completion = "Let's see here... what do we have...\n\n<Keritose buries his head in the papers for a bit, seemingly gleaning little that he did not already know. Suddenly he finds what he is looking for...>\n\nMalykriss! The Vile Hold. It seems Arthas did not take the loss of his death knights so well... I'm not exactly sure what he's doing with all of that saronite, but I have a feeling he might be overcompensating for something.\n\nThat boy is not used to losing.", sourceObjectiveStatus = "unverified-source-field" }
quests[13175] = { id = 13175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regaining Control" }
quests[13176] = { id = 13176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preparing the Delivery" }
quests[13177] = { id = 13177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Mercy for the Merciless", description = "Welcome to the Wintergrasp Fortress, {name}. Your mission is simple. Defeat ten of the Horde's finest. Now, go! Bring victory to the Alliance!", sourceObjective = "Commander Zanneth in Wintergrasp Fortress wants you to slay 10 members of the Horde.", completion = "Glorious! Truly, you are among the champions of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[13178] = { id = 13178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slay them all!", description = "Welcome to the Wintergrasp Fortress, {name}. Warlord Garrosh demands one thing: Slay them all!\n\nReturn to me when ten of the strongest members of the Alliance are dead.", sourceObjective = "Commander Dardosh in Wintergrasp Fortress wants you to slay 10 members of the Alliance.", completion = "Lok'tar! Victory for the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[13179] = { id = 13179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Mercy for the Merciless", description = "Welcome to Wintergrasp, {name}. Your mission is simple. Defeat ten of the Horde's finest. Now, go! Bring victory to the Alliance!", sourceObjective = "Commander Zanneth in Wintergrasp wants you to slay 10 members of the Horde.", completion = "Glorious! Truly, you are among the champions of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[13180] = { id = 13180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slay them all!", description = "Welcome to Wintergrasp, {name}. Warlord Garrosh demands one thing: Slay them all!\n\nReturn to me when ten of the strongest members of the Alliance are dead.", sourceObjective = "Commander Dardosh in Wintergrasp wants you to slay 10 members of the Alliance.", completion = "Lok'tar! Victory for the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[13181] = { id = 13181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory in Wintergrasp", description = "Commander Zanneth might be satisfied with a pile of Horde corpses at his feet, but controlling Wintergrasp is of the utmost importance to the Valiance Expedition. Make sure it remains in our control.\n\nHowever, don't think we'll just let you stand around while your allies do your dirty work for you. If you're not at least a second level recruit by the end of the battle, don't come back.", sourceObjective = "Win a Wintergrasp battleground match and return to Tactical Officer Abrahmis in Wintergrasp. You must have participated in the battle to be credited for the victory.", completion = "Just what I wanted to hear!  A victory in Lake Wintergrasp - even a temporary one - is crucial to our overall strategy against the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13182] = { id = 13182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Don't Forget the Eggs!", description = "Throughout Azjol-Nerub, the scourged nerubians carefully nurture eggs that will soon hatch, providing them even greater numbers.\n\nIt would do little good for the caverns to be cleansed of the undead that stain them if these fouled eggs were left to hatch and take their place.\n\nAs you  explore the expanse that was once Azjol-Nerub, be sure to clear our ancient home of any scourge eggs you find.", sourceObjective = "Kilix the Unraveler in the Pit of Narjun wants you to enter Azjol-Nerub and destroy 6 Nerubian Scourge Eggs.", completion = "It saddens me to see that things have come to this. If only we could return our great empire to what it once was...", sourceObjectiveStatus = "unverified-source-field" }
quests[13183] = { id = 13183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory in Wintergrasp", description = "While Dardosh might be content with slaying our foes, it is of the utmost importance that we control Wintergrasp Fortress. Do whatever it takes to ensure Wintergrasp is ours.\n\nHowever, don't think we'll just let you stand around while your allies do your dirty work for you. If you're not at least a second level recruit by the end of the battle, don't come back.", sourceObjective = "Win a Wintergrasp battleground match and return to Tactical Officer Kilrath in Wintergrasp. You must have participated in the battle to gain credit for the victory.", completion = "It is a truly great thing you have accomplished this day. Be recognized for your sacrifice!", sourceObjectiveStatus = "unverified-source-field" }
quests[13184] = { id = 13184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Outliving Usefulness" }
quests[13185] = { id = 13185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Siege", description = "I hears dem! The Alliance come soon. Destroy three Alliance siege devices and come back to Murp.", sourceObjective = "Lieutenant Murp in Wintergrasp Fortress wants you to destroy 3 Alliance siege machines.", completion = "Good job. Murp wish he was there to help.", sourceObjectiveStatus = "unverified-source-field" }
quests[13186] = { id = 13186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Siege", description = "It is only a matter of time before this castle is besieged by the forces of the Horde. Destroy three of their siege devices and return to me.", sourceObjective = "Senior Demolitionist Legoso in Wintergrasp Fortress wants you to destroy 3 Horde siege machines.", completion = "Excellent. That should slow down their assault.", sourceObjectiveStatus = "unverified-source-field" }
quests[13187] = { id = 13187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Faceless Ones", description = "In my peoples' struggle against the forces of the undead, they dug deeper as they lost ground.\n\nThey inadvertently exposed minions of the Old Gods known only as the Faceless.\n\nIn the end, we could not fight a war on two fronts.\n\nWith your aid, perhaps the Faceless will finally fall.", sourceObjective = "Seer Ixit in Ahn'Kahet wants you to kill Herald Volazj and the three Forgotten Ones that accompany him.", progress = "Have you overcome the faceless ones, {class}?", completion = "You have done well, {class}.\n\nWith the servants of the Old Gods defeated, the time is upon my people to retake our ancient home.", sourceObjectiveStatus = "unverified-source-field" }
quests[13188] = { id = 13188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Kings Walk", description = "You are now, and forever will be, a Knight of the Ebon Blade, {name}, but know this: you were once a hero of the Alliance.\n\n<Darion stares at you.>\n\nThis order must establish allies for itself if it is to survive. You must represent the Knights of the Ebon Blade to the Alliance.\n\nOn the platform, southeast of me, is a portal to Stormwind City. Take this letter, given to me on your behalf by Lord Fordring, and deliver it to King Varian Wrynn. Use the portal.", sourceObjective = "Deliver the letter to King Varian Wrynn of the Alliance at Stormwind Keep in Stormwind City.", progress = "You have mere moments to live.", completion = "<Varian stares off into the distance.>\n\nIndeed old friend... Blood and honor.\n\n<Varian affixes his gaze upon you.>\n\nWere it not for this letter from Tirion, you would be a stain upon my floor. Only an endorsement from one of the greatest paladins to ever live could have ensured your survival.\n\nWe... We will work together against the Scourge. Against the Lich King!\n\nGLORY TO THE ALLIANCE!", sourceObjectiveStatus = "unverified-source-field" }
quests[13189] = { id = 13189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Blessing", description = "You are now, and forever will be, a Knight of the Ebon Blade, {name}, but know this: you were once a hero of the Horde.\n\n<Darion stares at you.>\n\nThis order must establish allies for itself if it is to survive. You must represent the Knights of the Ebon Blade to the Horde.\n\nOn the platform, southeast of me, is a portal to Orgrimmar. Take this letter, given to me on your behalf by Lord Fordring, and deliver it to the Warchief. Use the portal.", sourceObjective = "Deliver the letter to the Warchief of the Horde at Orgrimmar.", progress = "An interesting turn of events.", completion = "Eitrigg is alive because of this paladin. He would have been executed had Lord Fordring not broken him out of Stratholme.\n\nTirion Fordring, to have sacrificed everything to save the life of an orc... I have ever only known one other human to make such a sacrifice.\n\n<Thrall blinks back a tear.>\n\nYou will be in my heart always, Taretha.\n\nYes. For Tirion Fordring and for Eitrigg! We will accept you as a member of the Horde and your order as allies.\n\nBlood and honor! For the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[13190] = { id = 13190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Things in Good Time", description = "Ahn'kahet, from whence we came...\n\nOne day, I dream, we shall overcome the death and darkness that hold our ancient home in their grip. To that end, I have a plan to weaken the resolve of our enemies.\n\nTheir precious Watchers must burn!\n\nTake their corpses and place them upon the brazier deep within the city. The scent of their burnt remains will linger in the air, reminding our enemy of their weakness.\n\nBe mindful, {class}! Their undead corpses are most fragile and will deteriorate rapidly.", sourceObjective = "Kilix the Unraveler in the Pit of Narjun wants you to obtain an Ahn'kahar Watcher's Corpse and place it upon the Ahn'kahet Brazier in Ahn'kahet.\n\nThis quest can only be completed on Heroic Difficulty.", progress = "Were you able to burn a Watcher's corpse, {race}?", completion = "Ahah!\n\nMay the mocking scent of failure eat at their empty souls!\n\nThank you, {class}. Today, you have struck a blow against the unliving.", sourceObjectiveStatus = "unverified-source-field" }
quests[13191] = { id = 13191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fueling the Demolishers", description = "Lok'tar, {name}! While the battle may be over, we must prepare for the Alliance's next assault! Travel to the Cauldron of Flames in south eastern Wintergrasp and retrieve ten eternal embers.\n\nThe embers are mixed in with coal to fuel the Demolishers and Siege Engines. \n\nWe've heard reports of Alliance pigs collecting the embers all day. Slay them and take their embers! If they have already abandoned the area, then be prepared to fight the fire elementals there until you find some!", sourceObjective = "Siegesmith Stronghoof at Wintergrasp Fortress wants you to retrieve 10 Eternal Embers from Alliance players in the Cauldron of Flames.", progress = "Well? Did you manage to find the embers or did the Alliance beat you to it and leave you crying?", completion = "Excellent! This will help us defeat the Alliance in the battles to come!", sourceObjectiveStatus = "unverified-source-field" }
quests[13192] = { id = 13192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warding the Walls", description = "Hey 'mon. This place be givin' me dah heebie jeebies, don't cha know?\n\nWay too many spirits haunting dis place. I want ta be placing hoodoo wards up, but I be needin' some souls, mon. Not any soul though, only da soul of a strong warrior could do da job.\n\nThe Glacial Falls in east Wintergrasp be havin' dem special properties to extract da soul. Slay the Alliance there, mebbe they be havin' the stuff we need.\n\nBring back da armor of the slain. If there be no Alliance maybe da elementals got 'em, mon.", sourceObjective = "Hoodoo Master Fu'jin at Wintergrasp Fortress wants you to retrieve 10 Enchanted Alliance Breastplates at the Glacial Falls.", progress = "Did ya bring da armor, mon?", completion = "Ooh, ya dats da stuff, mon!", sourceObjectiveStatus = "unverified-source-field" }
quests[13193] = { id = 13193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bones and Arrows", description = "Why would they set me to the task of arming our archers? I was a poet, not a ranger! Well, no use complaining. {name}, I am in need of dragon bone for our arrowheads.\n\nTravel to the Forest of Shadows on the western side of Wintergrasp. Ever since the last skirmish, the Alliance have been scavenging dragon bones in the area. Slay them and take the bones.\n\nIf that fails, you might be lucky and get one from the spirits in the area. I hear they love to impale their living victims on the bones as they die.", sourceObjective = "Lieutenant Vieron Blazefeather at Wintergrasp Fortress wants you to retrieve 10 Quivers of Dragonbone Arrows from Alliance players in the Forest of Shadows.", progress = "Back so soon? Drat, I was hoping to catch a moment's rest.", completion = "Well, I guess its another night of sharpening bones for me. Why didn't I stay in Silvermoon City like my brother?", sourceObjectiveStatus = "unverified-source-field" }
quests[13194] = { id = 13194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Healing with Roses", description = "Between the battles, one might almost believe that there was hope for peace in this land. Sadly, that is not to be our fate.\n\nTravel to the Steppe of Life in southwestern Wintergrasp. I have need of the roses that grow there for salve to treat the wounded.\n\nSadly, the rose has become scarce due to the Alliance harvesting it too rapidly. Slay them on the Steppe of Life and retrieve their herb pouches from the bodies.\n\nIf that fails, perhaps a lasher or two might have one.", sourceObjective = "Primalist Mulfort wants you to retrieve 10 Alliance Herb Pouches from Alliance players at the Steppe of Life.", progress = "Were you able to recover the herbs? The sick and wounded increase by the hour.", completion = "Thank you, this will go far to treat our soldiers' wounds.", sourceObjectiveStatus = "unverified-source-field" }
quests[13195] = { id = 13195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Rare Herb", description = "My, it is quite chilly up here! Reminds me of the stormy peaks of Kaarinos on Argus. However, with all of this snow and ice, our soldiers can easily catch cold.\n\nHead to the Steppe of Life in southwestern Wintergrasp, and bring me back 10 Horde Herb Pouches. I will grind the herbs into a medicine to protect against the cold.\n\nThe Horde have been seen collecting them from the plant life in the area. Do not hesitate to slay them and retrieve the herbs!\n\nYou may also find one on a lasher in the area.", sourceObjective = "Anchorite Tessa in Wintergrasp wants you to retrieve 10 Horde Herb Pouches from Horde players in the Steppe of Life.", progress = "I hope you didn't pull up any of the lashers by mistake! They gave Private Doane quite a whipping last week.", completion = "Excellent! This will help protect our troops against the cold.", sourceObjectiveStatus = "unverified-source-field" }
quests[13196] = { id = 13196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bones and Arrows", description = "Dragons are incredible! Well, their bones at least! I've been equipping our archers with arrowheads made of Dragonbone. Unfortunately, since the massacre at Angrathar, it has become almost impossible to get bone from Dragonblight.\n\nHowever, the Forest of Shadows on the western edge of Wintergrasp has enough bones to tide us over.\n\nHead to the Forest of Shadows and bring back any bone splinters you can find!\n\nThe Horde have been seen collecting bone splinters in the area. Slay them!", sourceObjective = "Bowyer Randolph in Wintergrasp wants you to retrieve 10 Quivers of Dragonbone Arrows from Horde players at the Forest of Shadows.", progress = "How was the hunting? I've heard rumors the place is haunted, though I never venture out there myself.", completion = "Excellent! This will help fuel the flames of war for days to come.", sourceObjectiveStatus = "unverified-source-field" }
quests[13197] = { id = 13197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fueling the Demolishers", description = "{name}! About time you showed up. While we may have lost the last battle, we should prepare for the next! Travel to the Cauldron of Flames in southeastern Wintergrasp and retrieve several eternal embers.\n\nThe embers are mixed in with coal to fuel the Demolisher and Siege Engines. \n\nOh, and if you happen to see some of the Horde in the Cauldron, don't hesitate to slay them and take their embers. We must prevent them from holding the keep!", sourceObjective = "Siegesmith Stouthandle in Wintergrasp wants you to retrieve 10 Eternal Embers from Horde players at the Cauldron of Flames.", progress = "Well? Did you manage to find the embers or did the Horde beat you to it and leave you crying?", completion = "Excellent! This will help fuel the flames of war for days to come.", sourceObjectiveStatus = "unverified-source-field" }
quests[13198] = { id = 13198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warding the Warriors", description = "{name}, good to see you. We must prepare for our next assault on the fortress. My research indicates that the armor of soldiers recently slain in the Glacial Falls becomes imbued with an incredible amount of energy. The Horde has been collecting armor in the area.\n\nHead to the Glacial Falls and slay any of the Horde you find there. Return their imbued armor to me.\n\nIf you cannot find any of the Horde, you might find the armor of an adventurer slain by the elementals.", sourceObjective = "Sorceress Kaylana in Wintergrasp wants you to retrieve 10 sets of Imbued Horde Armor at the Glacial Falls.", progress = "So, did you find the armor?", completion = "Augh. It's still dripping. Couldn't you have at least dried it off first?", sourceObjectiveStatus = "unverified-source-field" }
quests[13199] = { id = 13199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bones and Arrows", description = "Why would they set me to the task of arming our archers? I was a poet, not a ranger! Well, no use complaining. {name}, I am in need of dragon bone for our arrowheads.\n\nTravel to the Forest of Shadows on the western side of Wintergrasp. Ever since the last skirmish, the Alliance have been scavenging dragon bones in the area. Slay them and take the bones.\n\nIf that fails, you might be lucky and get one from the spirits in the area. I hear they love to impale their living victims on the bones as they die.", sourceObjective = "Lieutenant Vieron Blazefeather in Wintergrasp wants you to retrieve 10 Quivers of Dragonbone Arrows from Alliance players at the Forest of Shadows.", progress = "Back so soon? Drat, I was hoping to catch a moment's rest.", completion = "Well, I guess its another night of sharpening bones for me. Why didn't I stay in Silvermoon City like my brother?", sourceObjectiveStatus = "unverified-source-field" }
quests[13200] = { id = 13200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fueling the Demolishers", description = "Lok'tar, {name}! While the battle may have subsided, we must prepare to retake the fortress! Travel to the Cauldron of Flames in south eastern Wintergrasp and retrieve ten eternal embers.\n\nThe embers are mixed in with coal to fuel the Demolishers and Siege Engines. \n\nWe've heard reports of Alliance pigs collecting the embers all day. Slay them and take their embers! If they have already abandoned the area, then be prepared to fight the fire elementals there until you find some!", sourceObjective = "Siegesmith Stronghoof in Wintergrasp wants you to retrieve 10 Eternal Embers from Alliance players at the Cauldron of Flames.", progress = "Well? Did you manage to find the embers or did the Alliance beat you to it and leave you crying?", completion = "Excellent! That should put a dent in their war machines!", sourceObjectiveStatus = "unverified-source-field" }
quests[13201] = { id = 13201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Healing with Roses", description = "So many of our braves were lost during the battle, but even more shall die if left untreated. \n\nTravel to the Steppe of Life in southwestern Wintergrasp. I have need of the roses that grow there for salve to treat the wounded.\n\nSadly, the rose has become scarce due to the Alliance harvesting it too rapidly. Slay them on the Steppe of Life and retrieve their herb pouches from the bodies.\n\nIf that fails, perhaps a lasher or two might be in bloom.", sourceObjective = "Primalist Mulfort in Wintergrasp wants you to retrieve 10 Alliance Herb Pouches from Alliance players at the Steppe of Life.", progress = "Were you able to recover the herbs? The sick and wounded increase by the hour.", completion = "Thank you, this will go far to treat our soldiers' wounds.", sourceObjectiveStatus = "unverified-source-field" }
quests[13202] = { id = 13202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jinxing the Walls", description = "Hey 'mon. See dem Alliance sitting comfy in their keep?\n\nI think they be a bit too comfy, ya? I want ta be jinxing the place, but I be needin' some souls, mon. Not any soul though, only da soul of a strong warrior could do da job.\n\nThe Glacial Falls in east Wintergrasp be havin' dem special properties to extract da soul. Slay the Alliance there, they be havin' the stuff we need.\n\nBring back da armor of the slain. If there be no Alliance maybe da elementals got 'em, mon.", sourceObjective = "Hoodoo Master Fu'jin in Wintergrasp wants you to retrieve 10 Enchanted Alliance Breastplates from Alliance players at the Glacial Falls.", progress = "Did ya bring da armor, mon?", completion = "Ooh, ya dats da stuff, mon!", sourceObjectiveStatus = "unverified-source-field" }
quests[13203] = { id = 13203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift" }
quests[13204] = { id = 13204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funky Fungi", description = "A misshapen piece of mushroom-like fungus falls from a particularly smelly, ooze-covered patch of the cave beast's flesh. Examining it, you are violently repulsed by its overwhelming stench.\n\nYou wonder to yourself if this is the kind of thing that the nerubians might find appetizing. Placing the sticky organism in your pack, you determine to find out...", sourceObjective = "You are to collect 6 Grotesque Fungus from Savage Cave Beasts in Ahn'kahet and deliver them to Kilix the Unraveler in The Pit of Narjun.", progress = "What in creation are these?!", completion = "Do you have any idea what you've been carrying around, {class}?\n\nThe cave beasts you've been harvesting have no traditional method of excreting their waste. You might want to wash your hands...\n\nThank you for the thought, but if you come across any more of these please keep them for yourself.", sourceObjectiveStatus = "unverified-source-field" }
quests[13205] = { id = 13205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disarmament", description = "Take it from me, <lad/lass>, them vrykul weapons be downright nasty!\n\nI've felt their edge personally, and there be somethin' unnatural about 'em. Deceptively well-balanced, wickedly sharp - just plain deadly.\n\nGet into their stronghold and if nuthin' else, pilfer some o' them weapons! Mebbe we can learn us a thing 'er two about 'em, mebbe not.\n\nBottom line - the fewer axes they be swingin' around, the better.", sourceObjective = "Defender Mordun wants you to enter Utgarde Keep and steal 5 Vrykul Weapons", progress = "You pinch a load a' them vrykul axes?", completion = "<Mordun whistles.>\n\nWill ya just look at 'em? Incredible.\n\nI half expected these neanderthals to be swingin' around clubs and throwin' rock.\n\nNo such luck...", sourceObjectiveStatus = "unverified-source-field" }
quests[13206] = { id = 13206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disarmament", description = "We must discover the secret to these savages' weapons!\n\nIf you'd have seen how easily they cut through my companions, you'd understand my sense of urgency.\n\nScour the place. Gather all of their arms that you can carry.", sourceObjective = "Dark Ranger Marrah wants you to steal 5 Vrykul Weapons from Utgarde Keep and bring them to her inside Utgarde Keep.", progress = "Were you able to steal their arms?", completion = "Every blade we take from them is one less embedded in a soldier's flesh.\n\nThank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13207] = { id = 13207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Stone", description = "Well now, I'm surprised to see other adventurers in a place such as this.\n\nIf my research on these halls is accurate, there be monumental discoveries to be made here!\n\nAssumin' I can count on ya to watch my back, you're welcome to tag along.", sourceObjective = "Brann Bronzebeard wants you to accompany him as he uncovers the secrets that lie in the Halls of Stone.", progress = "Well, now, it turned out ta be a good thing we ran into each other after all.", completion = "Always more questions than answers, eh, lad?", sourceObjectiveStatus = "unverified-source-field" }
quests[13211] = { id = 13211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "By Fire Be Purged", description = "The Scourge uses our own fallen against us, by raising them as ghouls or skeletons, or by dismembering their corpses and using the parts to make abominations. This must stop!\n\nThe dead are heroes who fell in defense of all the living, and they cannot be confined to so grisly a fate. Moreover, we cannot afford to face them again on the field, used as weapons against us. Take this torch with you to the Fleshwerks, and burn any of the corpses you find in the Sanctum of Reanimation or the abomination lab.", sourceObjective = "Crusader Olakin Sainrith at Blackwatch wants you to burn 7 Festering Corpses using Olakin's Torch.", completion = "<Crusader Olakin Sainrith listens solemnly to your report.>\n\nIt is not the burial they deserved, but it is better than nothing, and better for those who yet live. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13212] = { id = 13212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He's Gone to Pieces", description = "With the abduction of Crusader Olakin, the Argent Crusade's forces will have no commander in the final assault on the Fleshwerks. While one crusader is the same as any other to me, the argents won't see it that way.\n\nI hate to see us waste time chasing after this, but I have no choice. Our gallant crusader has likely been dismembered by now, and his remains used to construct abominations. Go down into the Fleshwerks, kill the corpulent horrors fighting our forces, and recover Olakin's body parts.", sourceObjective = "Recover Olakin's Torso, Olakin's Legs, Olakin's Left Arm, and Olakin's Right Arm and bring them to Darkrider Arly at Blackwatch.", progress = "Have you recovered the, uh, remains of Crusader Olakin?", completion = "Well, I suppose it's good that we've \"recovered\" the crusader, though I doubt his comrades had this in mind. Let's see what we can do to get him back on his feet so we can get this charade over with and complete our mission here.", sourceObjectiveStatus = "unverified-source-field" }
quests[13213] = { id = 13213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle at Valhalas", description = "I see and hear many things, {name}, and something very important has happened since your defeat of Overthane Balargarde: you are wanted for battle in Valhalas!\n\nYou will find the battle pit to the north. Go now with your friends and speak with Geirrvif the val'kyr. The challengers that she will offer you within Valhalas are sure to require their help.\n\nGood luck.", sourceObjective = "Speak with Geirrvif in Valhalas.", completion = "You have bested our finest warriors. Your name is renowned, {name}.\n\nPerhaps you think that this concerns me: it does not. If they can fall to you then they are not worthy and should be nothing but lowly vargul!\n\nBut perhaps I can give you and your friends different sport. Valhalas is also a place for combat of all types with many different kinds of foes.\n\nSpeak to me again when you and your friends are ready to proceed. We shall see if you are truly worthy.", sourceObjectiveStatus = "unverified-source-field" }
quests[13214] = { id = 13214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle at Valhalas: Fallen Heroes", description = "If you believe yourself ready to begin then I have just the match for you to cut your teeth on.\n\nAnother group of outsiders thought themselves prepared for the rigors of Valhalas. They had much hubris, but in the end they fell like all of the others.\n\nIf you think yourselves so different -- if you think that you have the skill and experience to fight here amongst such storied warriors -- then please accept the challenge.", sourceObjective = "Geirrvif at Valhalas has challenged you to, in a single combat, defeat all six of the fallen heroes: Eldreth, Geness Half-Soul, Jhadras, Masud, Rith, and Talla.\n\nShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.", completion = "New blood.\n\n<The vrykul death knight spits on the ground at your feet.>\n\nYou all think that you have what it takes to fight here.\n\nYou are nothing before the might of the vrykul and the Scourge!\n\nStill, you did manage to defeat six incompetent corpses, so you must have some skill in you. Not likely enough for the next challenge though.", sourceObjectiveStatus = "unverified-source-field" }
quests[13215] = { id = 13215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle at Valhalas: Khit'rix the Dark Master", description = "A variety of beings travel the world to prove themselves within Valhalas. Some even come from under the world.\n\nKhit'rix the Dark Master is one such.\n\nHailing from deep within the ground where insanity reigns, Khit'rix has asked for someone exotic to face in the ring. You will do.\n\nDare you face this Nerubian nightmare, {race}?", sourceObjective = "Geirrvif at Valhalas has challenged you to defeat Khit'rix the Dark Master.\n\nShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.", completion = "You want me to be impressed by the fact that you and your friends were able to bring down a lone Nerubian priest?\n\nGet out of my sight before I summon my ghouls upon you!", sourceObjectiveStatus = "unverified-source-field" }
quests[13216] = { id = 13216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle at Valhalas: The Return of Sigrid Iceborn", description = "An old foe of yours has returned: Sigrid Iceborn. Perhaps you remember besting her in a duel upon the Savage Ledge?\n\nNo matter, she certainly remembers you. She's insisting upon a chance to prove herself once more.\n\nPersonally, I think it's more a chance for revenge, but that too can be useful in this place.\n\nI leave it up to you, {name}. Will you face Sigrid Iceborn once more?", sourceObjective = "Geirrvif at Valhalas has challenged you to defeat Sigrid Iceborn.\n\nShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.", completion = "The defeat of one of the hyldnir is mildly impressive, {race}, but you did have the help of your friends.\n\nYou're lucky that her drake didn't get involved.", sourceObjectiveStatus = "unverified-source-field" }
quests[13217] = { id = 13217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle at Valhalas: Carnage!", description = "You've been successful up to this point, {name}, but what you must face to continue to battle within Valhalas is a gigantic horror beyond imagining.\n\nI must warn you to turn away now. Carnage is a mountain of flesh constructed by the Lich King's most fiendish minds.\n\nI do not see how you and your friends will defeat it. However, the choice is yours.", sourceObjective = "Geirrvif at Valhalas has challenged you to defeat Carnage.\n\nShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.", completion = "I'm starting to respect your prowess in the ring, {name}. Now I really don't like you.\n\nI would much rather have preferred to see you and your friends stuck to the bottom of that flesh giant's foot!", sourceObjectiveStatus = "unverified-source-field" }
quests[13218] = { id = 13218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle at Valhalas: Thane Deathblow", description = "Your skills have not gone unnoticed by the vrykul of Jotunheim, {name}. Thane Banahogg has taken a personal interest in you and has insisted that he be your next match.\n\nIf you thought Carnage was bad, then you might want to go home now. Thane Banahogg's nickname is The Deathblow. I think you can guess how he earned it.\n\nDo you accept the thane's challenge?", sourceObjective = "Geirrvif at Valhalas has challenged you to defeat Thane Banahogg, the Deathblow.\n\nShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.", completion = "I don't know what trickery it was that you used to bring down the thane -- I couldn't see it from this angle -- but I can assure you that you will not survive your next match.\n\nYes, I know who it is. Run, little {race}. Flee to the far corners of the world.\n\nOr stay and die. It matters little to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[13219] = { id = 13219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle at Valhalas: Final Challenge", description = "I'm afraid that your success is going to be your undoing, {name}.\n\n<If the val'kyr could turn more white, she would.>\n\nWord of your success in Valhalas has reached deep into Icecrown Citadel, stirring one whom you have no desire to meet.\n\nPrince Sandoval himself is on his way at this very moment. Gjonner warned you that you should run and I cannot disagree.\n\nWhat will you do? He's on his way. Will you face the blood prince in final battle?", sourceObjective = "Geirrvif at Valhalas has challenged you to defeat Prince Sandoval.\n\nShould you succeed, speak with Gjonner the Merciless overlooking the southern lip of Valhalas.", progress = "I laugh at you. I knew that it would come to this in the end.\n\nNo matter what you do, no matter where you run, Prince Sandoval will find you!", completion = "Your defeat of Prince Sandoval sickens me. An unwashed peasant such as yourself should have willingly given over his life simply for the chance to meet him and kneel at his feet.\n\nYou've earned your damned reward. Be quick about your choosing.", sourceObjectiveStatus = "unverified-source-field" }
quests[13220] = { id = 13220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting Olakin Back Together Again", description = "We can't afford to waste any time putting Olakin back together. Fortunately, the Scourge has provided a perfect place for you to stitch him back together.\n\nNear the Fleshwerks' flesh giant lab is the Sanctum of Reanimation. Search the area for a spool of thread and the doctor's cleaver. Then, take Olakin's remains to the large slab in the middle of the sanctum and get to work.", sourceObjective = "Obtain a Spool of Thread and the Doctor's Cleaver, then take them to the Sanctum of Reanimation Slab and use Olakin's remains to attempt to reanimate the crusader. Return to Darkrider Arly at Blackwatch when this task is complete.", progress = "Have you put our brave crusader back together?", completion = "Olakin should consider himself fortunate. No one is rescued from the Scourge, no one. No amount of thread and heroism will save him a second time. I'll make certain he remembers it.", sourceObjectiveStatus = "unverified-source-field" }
quests[13221] = { id = 13221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm Not Dead Yet!", description = "The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their 'work' here if I cannot escape.\n\nI cannot make it on my own, my child, but with your help, I may yet live to fight the Scourge again.\n\nWill you help me make my escape before the Scourge's butchers come to finish me off?", sourceObjective = "Escort Father Kamaros to safety and then report to Absalan the Pious aboard the Skybreaker.", completion = "Thank the Light. I'd thought Father Kamaros dead, or worse. Through your bravery and compassion, you have restored a great ally to the Argent Crusade. You have my thanks and those of the crusade.", sourceObjectiveStatus = "unverified-source-field" }
quests[13222] = { id = 13222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defend the Siege", description = "Front and center, {name}! We're beginning our assault on Wintergrasp Fortress. Those Horde animals think they can hide cowardly behind their walls? Well, I think not! We'll show them the power of Gnomish technology and smash their walls to bits!\n\nHowever, even the most powerful siege device is helpless without a crew. Pilot or protect one of our siege vehicles as it destroys three of the Horde structures.", sourceObjective = "Senior Demolitionist Legoso in Wintergrasp wants you to pilot or protect a siege device as it destroys three structures.\n\nPlayers of private rank or higher can build siege devices at Goblin Workshops.", completion = "That should show them the power of Gnomish invention!", sourceObjectiveStatus = "unverified-source-field" }
quests[13223] = { id = 13223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defend the Siege", description = "Dem Alliance won't be long to hold that keep. Murp would smash walls, but Murp has to stay in camp. Murp wish he could smash Alliance who want to hurt Horde demolishers.\n\nYou, {name}! You go in Murp's place. Protect 3 siege vehicles while they smash Alliance buildings. Alliance not expect you to defend demolisher. Show Alliance how smart Murp is!", sourceObjective = "Lieutenant Murp in Wintergrasp wants you to defend or pilot a siege vehicle while they destroy three Alliance structures.\n\nSiege devices can be built by ranked Horde players at the Goblin Workshops.", completion = "Good job. Murp wish he was there to help.", sourceObjectiveStatus = "unverified-source-field" }
quests[13224] = { id = 13224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orgrim's Hammer", description = "The Argent Crusade pulled my ravaged body from the Broken Front. What a glorious battle, {race}. My axe sang as it cut down Alliance filth and Scourge alike.\n\nMy time is over. It will be a good death. Carry a message for me, soldier.\n\nOur base flies out of reach of Scourge - overhead between Mord'rethar and Aldur'thar. It is called \"Orgrim's Hammer.\"\n\n<Hork futilely attempts to salute.>\n\nFly high and avoid the Alliance juggernaut, Skybreaker. Tell Korm... tell him I died... fighting... For the Horde.", sourceObjective = "Seek out Sky-Reaver Korm Blackscar aboard Orgrim's Hammer flying above Icecrown.", completion = "<Korm salutes.>\n\nDamn the Scourge and damn the Alliance! Hork was one of our best. We will have our revenge. For Hellscream and for the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[13225] = { id = 13225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Skybreaker", description = "We were neck deep in Scourge and Horde. The screams of the dying covered that field. It was torturous... unrelenting!\n\nAt some point my body gave out. I fell, only to be awoken by the Argent Crusade. They pulled me out of the Broken Front and brought me here. I'm not going to make it. Grant a dying soldier one last wish, {race}? Our base, the Skybreaker, flies high above Icecrown. It is there that you'll find my commanding officer, High Captain Bartlett. Tell him that I died a soldier of the Alliance.", sourceObjective = "Seek out High Captain Justin Bartlett aboard the Skybreaker flying above Icecrown.", completion = "<Captain Bartlett salutes.>\n\nHe was a damn fine soldier. Damn the Horde and damn the Scourge!", sourceObjectiveStatus = "unverified-source-field" }
quests[13226] = { id = 13226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Judgment Day Comes!", description = "We cannot defeat the Lich King on our own. Divided we shall all fall!\n\nI implore you to answer the call, <brother/sister>. The Argent Crusade accepts all who would volunteer to aid in the war effort. Highlord Tirion Fordring himself awaits you at the Argent Vanguard! Get upon your mount and fly to the southeastern reaches of Icecrown. It is there that you will find Lord Fordring and the soldiers of the Argent Crusade.\n\nGo now, {class}, for judgment day comes!", sourceObjective = "Report to Highlord Tirion Fordring at the Argent Vanguard in Icecrown.", completion = "My faithful knights have served me well. It seems that their recruitment efforts have yielded a hero!", sourceObjectiveStatus = "unverified-source-field" }
quests[13227] = { id = 13227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Judgment Day Comes!", description = "We cannot defeat the Lich King on our own. Divided we shall all fall!\n\nI implore you answer the call, <brother/sister>. The Argent Crusade accepts all that would volunteer to aid in the war effort. Highlord Tirion Fordring himself awaits you at the Argent Vanguard! Get upon your mount and fly to the southeastern reaches of Icecrown. It is there that you will find Lord Fordring and the soldiers of the Argent Crusade.\n\nGo now, {class}, for judgment day comes!", sourceObjective = "Report to Highlord Tirion Fordring at the Argent Vanguard in Icecrown.", completion = "My faithful knights have served me well. It seems that their recruitment efforts have yielded a hero!", sourceObjectiveStatus = "unverified-source-field" }
quests[13228] = { id = 13228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Broken Front", description = "What battle?! Those troops were on a recon mission!\n\nAnd what's this talk of Alliance - you're sure he said Alliance?\n\nListen to me, {name}! I need to know what's going on and I need to know NOW!\n\nGet yourself down there and get me some answers! Scour the battlefield and look for survivors - clues - anything!", sourceObjective = "Korm Blackscar on Orgrim's Hammer wants you to go to The Broken Front and question a Dying Berserker to discover what happened there.", completion = "They saw the Alliance assaulting the gate and they attacked them from behind...\n\n<After a brief pause, Korm bursts into laughter.>\n\nTHAT is what it means to be HORDE!\n\nWere it not for them, the Alliance maggots would likely be holding that gate!\n\nTheir boldness has bought us precious time.", sourceObjectiveStatus = "unverified-source-field" }
quests[13229] = { id = 13229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm Not Dead Yet!", description = "The Light smiles upon me. I have not yet died in this living nightmare, but the Scourge will kill me and tear my body apart for use in their 'work' here if I cannot escape.\n\nI cannot make it on my own, {class}, but with your help, I may yet live to fight the Scourge again.\n\nWill you help me make my escape before the Scourge's butchers come to finish me off?", sourceObjective = "Escort Father Kamaros to safety and then report to Brother Keltan aboard Orgrim's Hammer.", completion = "You have done well. We thought Father Kamaros lost, for certain. Your bravery will serve as an example to all those who oppose the Scourge.", sourceObjectiveStatus = "unverified-source-field" }
quests[13230] = { id = 13230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avenge Me!", description = "I hear them, <brother/sister>....\n\nThe moans of the wounded Alliance... they taunt me...\n\nFinish what we have begun here, {class}. Show no mercy... let none of them survive.\n\nFor... the Horde...", sourceObjective = "A Dying Berserker has asked that you slay 5 Dying Soldiers at the Broken Front. Report to Sky-Reaver Korm Blackscar on Orgrim's Hammer when it is done.", completion = "The time of tolerance for the Alliance has passed, {name}.\n\nThey have earned our hatred! They shall live in fear of the Horde until they no longer pollute our world!", sourceObjectiveStatus = "unverified-source-field" }
quests[13231] = { id = 13231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Broken Front", description = "What?! Noooo!\n\nWe went to such great pains to keep this attack secret. How could the Horde have known? The resources... the men... all lost? Inconceivable!\n\nOur plans here in Icecrown hinged upon our taking that gate before the Horde could. We must recover quickly and prepare to mount another offensive.\n\nVisit the battlefield and search for any survivors. See if there's anything to be learned from this tragedy.\n\nAnd prepare yourself, {name}, for a war - on two fronts...", sourceObjective = "High Captain Justin Bartlett aboard the Skybreaker wants you to go to the Broken Front and question a Dying Soldier, then report back to him.", completion = "So... It was a rout - a total loss. This shall not be forgotten.\n\nMark my words, {class}. The Horde shall pay for this... there will be no mercy!", sourceObjectiveStatus = "unverified-source-field" }
quests[13232] = { id = 13232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finish Me!", description = "They taunt us - even as they lie dying here...\n\nPlease, <brother/miss>... Don't allow their mocking to be the last sounds I hear...\n\nFinish me... deliver me from this torment... into... the Light.\n\nSeek out  my companions... offer them the same mercy.\n\nLeave nothing for the Scourge to raise!\n\nI beg you...", sourceObjective = "A Dying Soldier in the Broken Front wants you to kill 5 Dying Soldiers and report to High Captain Justin Bartlett on the Skybreaker.", completion = "That was a difficult thing you did, {class}. But it was the right thing.\n\nDon't allow the memory of your actions to haunt you. Harness that sorrow and pain you feel! Direct it at those who caused it.\n\nThe Horde must pay!", sourceObjectiveStatus = "unverified-source-field" }
quests[13233] = { id = 13233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Mercy!", description = "It is as I told you. They were not merely idle words spoken in a fit of anger.\n\nTime and again, the Horde have demonstrated their disdain for everything we hold dear and holy. They must pay with their lives for their transgressions against the light.\n\nAll of them.\n\nJust imagine a world free of their stain, {name}. Envision the joy our children will know. Think of the reverence your descendants will have for your memory, knowing they owe their happiness to you.\n\nNow go, and make that vision a reality!", sourceObjective = "High Captain Justin Bartlett aboard the Skybreaker wants you to kill 15 Horde Players in Icecrown.", completion = "Well done, {name}!\n\nHunt them down and make them pay!", sourceObjectiveStatus = "unverified-source-field" }
quests[13234] = { id = 13234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Them Pay!", description = "The time has come!\n\nToo long have we suffered the company of the self-righteous Alliance! Too long have we stayed our hand from cleansing our world of the weak and the desperate.\n\nNow, we bring an end to our humiliation! Now, we show them the true meaning of fear! Now, we bring honor to the Horde!\n\nHere, at Icecrown, we break the Alliance!\n\nGo, {class}. Hunt them down. Break them. Take their will to live!", sourceObjective = "Sky-Reaver Korm Blackscar wants you to kill 15 Alliance Players in Icecrown.", completion = "You have done well, {class}.\n\nSoon, the Alliance shall run from you in fear and the Horde shall honor your name!", sourceObjectiveStatus = "unverified-source-field" }
quests[13235] = { id = 13235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flesh Giant Champion", description = "You've done well in destroying the Fleshwerks and slaughtering the Lich King's servants. Now, all that remains is to defeat the Fleshwerks' greatest accomplishment -- the flesh giant known as Morbidus.\n\nIt will not be an easy fight, but the Shadow Vault has dispatched Margrave Dhakar with some reinforcements. Meet up with him at the highest point at the western end of the Fleshwerks. Tell him when you're ready to begin the attack and he'll order his forces into battle.", sourceObjective = "Speak with Margrave Dhakar at the western end of the Fleshworks to engage Morbidus. After you have defeated Morbidus, report to Darkrider Arly at Blackwatch.", progress = "Have you finished off the Lich King's prized flesh giant?", completion = "With the Lich King's flesh giant champion defeated, he must know that the rest of his forces are vulnerable as well. With you by our side, we will teach the Lich King the meaning of fear once more.", sourceObjectiveStatus = "unverified-source-field" }
quests[13236] = { id = 13236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Army of the Damned", description = "You probably think you're quite strong -- fighting these undead and crushing their bones beneath your war machines.\n\nThat is nothing compared to the strength it took to create them.\n\nI saw the prince do it himself.  I can show you how it happened... if you'd like.", sourceObjective = "Matthias Lehner at the First Legion Forward Camp wants you to raise an army of 100 Ghoulish Minions.", progress = "Did you see, {name}?", completion = "The prince's true power wasn't his ability to make armies out of corpses... that was easy.\n\nBut killing his own men, with whom he'd shared many battles... the prince's true power was his ability to do what had to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[13237] = { id = 13237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poke and Prod", description = "While your commander has his focus diluted by his loathing of your Alliance rivals, you can depend on me to direct my attention squarely on the real enemy here - the Lich King and his minions.\n\nIn order to hold any hope of conquering him at the citadel, your people must take and hold each gate.\n\nFor now, let us focus on the first. Return to the front and prod their defenses. Look for any sign of weakness that we might exploit.\n\nI'll await your report, {class}.", sourceObjective = "Koltira Deathweaver aboard Orgrim's Hammer wants you to go the Broken Front and defeat 5 Hulking Abominations, 5 Malefic Necromancers, and 5 Shadow Adepts.", completion = "Really, {class}?\n\nNothing notable to report?\n\n\n\nI beg to differ...", sourceObjectiveStatus = "unverified-source-field" }
quests[13238] = { id = 13238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good For Something?", description = "Goblins! Hyper little busy-bodies...\n\nListen, {name}. Copperclaw, our resident engineer, is insisting that he's got something useful to show me.\n\nI'm in no mood to endure his squeaky nagging. The last time I acknowledged him, he chirped on for an hour straight. It was all I could do to keep from drop-kicking him into Sindragosa's Fall!\n\nYou go in my place and humor him. Let me know if indeed he's on to anything.", sourceObjective = "Sky-Reaver Korm Blackscar wants you to speak with Chief Engineer Copperclaw aboard Orgrim's Hammer.", completion = "Too busy? Phooey! This baby flies herself!\n\nNevermind that. You'll do...", sourceObjectiveStatus = "unverified-source-field" }
quests[13239] = { id = 13239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volatility", description = "Where to begin... well, you must know that as chief engineer of this vessel I have access to all of the intelligence reports - yes, yes, it's true, and I've recently taken a particular interest in the frostwyrms you reported seeing to the south, and I do believe I've developed a plan that just might work against them... now it'll take a little legwork on your part, but essentially, you build a dummy out of armor and coat it with a splash of this solution, then run for cover!\n\n...You still here, {race}?", sourceObjective = "Chief Engineer Copperclaw wants you to use Copperclaw's Volatile Oil at the Broken Front to attract 3 Frostbrood Skytalons.\n\nTo use the oil, you must collect a Pile of Bones, an Abandoned Helm, and Abandoned Armor from the battlefield there.", completion = "Wahooo! I saw them light up all the way from here! I'll just chalk that up as another success and begin bottling this stuff up for the invasion - of course it might need a little more testing as we go if you're at all interested....", sourceObjectiveStatus = "unverified-source-field" }
quests[13240] = { id = 13240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timear Foresees Centrifuge Constructs in your Future!", description = "It is into the Oculus floating above Coldarra that you must travel, {name}.\n\nI have foreseen a situation in which you must destroy the centrifuge constructs therein. I can assure you that if you do not first eliminate these magical creations, you and your friends will fail.\n\nThus I have seen, thus you must do.", sourceObjective = "Archmage Timear in Dalaran has foreseen that you must destroy 10 Centrifuge Constructs.", completion = "<The archmage nods even before you say a word.>\n\nI know. You destroyed the constructs as I foresaw and were then able to go on to fight Varos Cloudstrider.\n\nExcellently done, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13241] = { id = 13241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timear Foresees Ymirjar Berserkers in your Future!", description = "King Ymiron's champions stand between you and victory in the not-too-distant future.\n\nYou will travel to the fortress known as Utgarde Pinnacle nestled deep within the woods of the Howling Fjord. I cannot stress how important it is that you and your traveling companions deal with the Ymirjar berserkers therein.\n\nFailure to do so may very well doom you, {name}!", sourceObjective = "Archmage Timear in Dalaran wants you to slay 7 Ymirjar Berserkers.", progress = "<The archmage presses his fingers to his temples and concentrates.>\n\nThe berserkers have not yet been slain. Heed my warning, {name}. You must do this thing!", completion = "Outstanding work, {name}.\n\nWithout having done so, the surviving berserkers would surely have swarmed you during your fight with the king.", sourceObjectiveStatus = "unverified-source-field" }
quests[13242] = { id = 13242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkness Stirs", description = "Darkness stirs, {name}. A tragic event has transpired that none but the Timeless One could have foreseen. Soon your people will be gripped by anger and hatred. War is on the horizon.\n\nThe red dragonflight has done all that it can. What happens next is in the hands of the mortal races of Azeroth.\n\nRegrettably, your journey begins with anguish. A father has lost a child today. You must bear the grim news. Gather the armaments of Saurfang and return them to the elder Saurfang.", sourceObjective = "Gather Saurfang's Battle Armor from the field of battle and return it to High Overlord Saurfang at Warsong Hold in Borean Tundra.", progress = "<Saurfang's face contorts.>\n\nMy heart... my strength...", completion = "<Saurfang looks to the heavens.>\n\nLike Brox, my son died a hero. Do not mourn him, {name}. For an orc, there could be no better end! No greater honor! At this moment, my heart swells with pride.\n\nI thank you for returning our battle armor. It will be placed upon his pyre at the Ancestral Grounds of Nagrand.\n\nWe must turn our full attention to more pressing matters.", sourceObjectiveStatus = "unverified-source-field" }
quests[13243] = { id = 13243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timear Foresees Infinite Agents in your Future!", description = "The timeline is in danger from the Infinite dragonflight. Without your intervention, all of time will unravel!\n\nYou must travel to a point in time known as the Culling of Stratholme within the Caverns of Time.\n\nIt gives me a migraine just to attempt to see into all of the possible pasts, but I do know that it is crucial for you to kill the Infinite agents.\n\nOnly by slaying them will the true past be preserved and the present and future kept from being undone forever!", sourceObjective = "Archmage Timear in Dalaran has foreseen that you must slay 4 Infinite Agents.", progress = "Time is always a precious resource, but even more so in this case, {name}. Please deal with the Infinite agents before it is too late!", completion = "We are saved for now. Thank you.\n\nUnfortunately due to the nature of their interference, the Infinite's will have almost unlimited opportunity to do so again.\n\nWhat I can discern is that in the future, you are at the heart of the struggle to stop them, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13244] = { id = 13244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timear Foresees Titanium Vanguards in your Future!", description = "The entirety of Azeroth is in peril. The mad god Loken has it within his power to put an end to everything!\n\nWithin the Terrestrial Watchtower at the Halls of Lightning, the titanium vanguards stand poised to execute Loken's dread will upon countless unknowing victims.\n\nI have looked into the future, {name}. You are the one to see that this does not come to pass!", sourceObjective = "Archmage Timear in Dalaran has foreseen that you must slay 7 Titanium Vanguards.", progress = "Even I cannot discern why it is that we are standing here speaking when you have yet to eliminate the threat of the titanium vanguards.", completion = "We are all in your debt, {name}.\n\nIf I am certain of anything, it is that you have not failed us, nor will you in the future!", sourceObjectiveStatus = "unverified-source-field" }
quests[13245] = { id = 13245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Ingvar the Plunderer", description = "I need you to assemble a group and lead them into Utgarde Keep. Therein, you are to find and slay Ingvar the Plunderer before he can lead his vrykul forces to sack the nearby Alliance and Horde towns.\n\nI require his axe as proof that he has been dealt with. It's not that I don't trust you. It's simply prudent to be certain that the deed has been done.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Axe of the Plunderer.\n\nThis quest may only be completed on Heroic difficulty.", progress = "You have the axe? Ingvar is dead?", completion = "Very well. Just put the axe down over by the wall.\n\nI'm sure that Valgarde and Vengeance Landing will rest easier tonight knowing that you have dealt with that savage.", sourceObjectiveStatus = "unverified-source-field" }
quests[13246] = { id = 13246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Keristrasza", description = "Are you familiar with the story of Keristrasza?\n\nHow she was instrumental in the slaying of Saragosa, the mate of Malygos? How, in turn, he took Keristrasza as his consort, freezing her within a block of ice?\n\nWe have become aware that Malygos has been using his magic to break her will. This has driven her insane.\n\n{name}, you must go into the Nexus in Coldarra and put an end to her before she can be fully turned.\n\nThough it saddens me, I must insist that you bring me her heart as proof.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with Keristrasza's Broken Heart.\n\nThis quest may only be completed on Heroic difficulty.", progress = "If we thought there was a way to redeem her, we wouldn't be asking you to put an end to her life.\n\nHowever, we know how powerful Malygos's command over magic has become. With his manipulations of Azeroth's ley-lines, he is without peer where matters arcane are concerned.", completion = "Regrettable, but extremely necessary.\n\nThe Kirin Tor could ill afford a prominent red dragon falling into the hands of our greatest enemy. Malygos's use of her against us in the Nexus War would have been devastating.\n\nI simply regret that we couldn't have saved her instead.", sourceObjectiveStatus = "unverified-source-field" }
quests[13247] = { id = 13247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Ley-Guardian Eregos", description = "The Nexus War rages on and we must do something to turn the tide! Are you willing to fly into the heart of the battle, {name}?\n\nLey-Guardian Eregos is the protector of the conduit through which Malygos is funneling the magical power of Azeroth's ley lines. If he can be slain it will be a great blow to the enemy.\n\nPlease bring me one of his ley line tuners so that we might study it.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with a Ley Line Tuner.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Has the ley-guardian been dealt with, {class}?\n\nI needn't remind you that Malygos is attempting to stop the use of all magic in the world, and that the blue dragonflight is slaying anyone that knows how to wield it who won't turn to their side?", completion = "Thank you, {name}. The examination of that tuner should provide us with further insights into how Malygos is manipulating the ley lines.\n\nIf we can find a weakness in his approach, we might be able to exploit it and turn the tide.", sourceObjectiveStatus = "unverified-source-field" }
quests[13248] = { id = 13248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: King Ymiron", description = "King Ymiron of Utgarde Pinnacle is the favored vrykul of the Lich King. That alone is reason enough to put an end to him.\n\nBut should he blow the horns and call for all of the leaders of the ymirjar and mjordin alike, the vrykul will become a force more powerful than any other within the Scourge!\n\nIt is up to you, {name}, to see to it that this does not come to pass. Bring me the locket from around his neck so that I will know that Ymiron no longer poses a threat.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Locket of the Deceased Queen.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Ymiron must not be allowed to organize the vrykul nation. Should he return triumphantly to Icecrown, it is very likely that all will be lost.", completion = "<The archmage somberly nods as you hand him the rather large piece of jewelry.>\n\nWhat's done is done. Such a noble race these vrykul. It is unfortunate that the Lich King has sunk his deathly hooks into them.", sourceObjectiveStatus = "unverified-source-field" }
quests[13249] = { id = 13249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: The Prophet Tharon'ja", description = "Drak'Tharon Keep once stood as a proud bastion of the Drakkari nation. Now it is nothing more than a stepping stone for the Lich King in his fight to put an end to Zul'Drak and steal the powers of the troll gods.\n\nBut if we were to eliminate their leader, the Prophet Tharon'ja, perhaps we could stop the flow of Scourge troll reinforcements. At the very least this would give the Argent Crusade in Zul'Drak one less thing to worry about.\n\nReturn to me with his tiki so I will know the prophet is slain.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Prophet's Enchanted Tiki.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Have you faced the prophet? Do you have the tiki?", completion = "With any luck, now that it's leaderless, Drak'Tharon Keep will now prove less of a thorn in the side of those fighting against the Scourge in the region.\n\n<The archmage looks down at the tiki in your hand.>\n\nIt's just as well that the tiki has lost its mojo. I wouldn't have the first idea about how to use it, or even if it would be proper to do such a thing.", sourceObjectiveStatus = "unverified-source-field" }
quests[13250] = { id = 13250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Gal'darah", description = "The Drakkari prophets of Zul'Drak have done the unthinkable: they've slain most of their gods to absorb their powers! The most dangerous of all is the High Prophet of Akali, Gal'darah.\n\nSequestered within the bowels of Gundrak, Gal'darah has absorbed almost all of the mojo from slain Akali and now stands poised to erupt with his followers from the city. If we do not kill him now, we will be awash in a sea of madness and unthinkable power!\n\nHurry, {name}, bring me what's left of Akali's mojo.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Mojo Remnant of Akali.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Do you have the mojo?\n\nIt is sickening to witness the demise of yet another great troll nation.\n\nI can only think that if it weren't for the interference of the Lich King, the trolls wouldn't have felt pressured to turn on their own gods and steal their power as a defense against the Scourge.", completion = "Thank you, {name}. I will see to it that the very essence of the god is kept safe until it can be handed over to the Zandalar tribe.\n\nPerhaps they'll be able to find a way to reincorporate Akali from it?", sourceObjectiveStatus = "unverified-source-field" }
quests[13251] = { id = 13251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Mal'Ganis", description = "{name}, a friend within the bronze dragonflight has given me information that we must exploit.\n\nThe mysterious beings of the Burning Legion called the dreadlords are also known racially as the Nathrezim. Little is known of their homeworld and even that is rumor.\n\nHowever, it is known that Mal'Ganis of the past has made a critical error: he left behind an artifact from his homeworld!\n\nThrough the Caverns of Time, you must travel back to the time known as the Culling of Stratholme. Recover the artifact.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Artifact from the Nathrezim Homeworld.\n\nThis quest may only be completed on Heroic difficulty.", progress = "We must capitalize on Mal'Ganis's mistake. It's not everyday that we get a chance like this.\n\nIf we can study that artifact, we may be able to gain a better understanding of the Nathrezim!", completion = "Amazing! I've never quite seen anything like it. I will see to it that it gets into the proper hands within the Violet Citadel.\n\nIf only you'd been allowed to change the course of history. Perhaps if Arthas had been kept from... no, down that path leads madness.\n\nSurely the Keepers of Time know best in these matters.", sourceObjectiveStatus = "unverified-source-field" }
quests[13252] = { id = 13252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Sjonnir The Ironshaper", description = "Little is understood about the condition known as the Curse of Flesh. However, there is information to be had within the Halls of Stone.\n\nSjonnir The Ironshaper seems to know a great deal with regard to the curse. We have it on good authority that he is carrying a Titan disc of information upon him that could answer all of our questions.\n\nRetrieve this disc for me, {name}, so that we may learn.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Curse of Flesh Disc.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Do you have the disc?", completion = "Is not Titan technology amazing? The information is contained within the disc itself!\n\nI only hope that we can figure out a way to get it out of the disc.", sourceObjectiveStatus = "unverified-source-field" }
quests[13253] = { id = 13253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Loken", description = "Within the Halls of Lightning, Loken is poised to put an end to our world. Need I say more, {name}?\n\nHe sits there listening to the mad whisperings of the Old God trapped beneath Northrend. You and your friends must travel to the Storm Peaks immediately!\n\nConfront Loken within the Terrestrial Watchtower and stop him before it is too late! Bring me his ruby ring so that I will know we are safe once more.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Celestial Ruby Ring.\n\nThis quest may only be completed on Heroic difficulty.", progress = "We speak again, {name}. Does this mean that we are safe from Loken's madness, or are we doomed?", completion = "<Archmage Lan'dalock breathes a sigh of relief.>\n\nTo be honest, I feared the worst had befallen you. It's difficult to stand idly by while others, such as yourself, deal with the matters of life and death which confront our world seemingly on a daily basis.\n\nNow what are we going to do with that gigantic ring?", sourceObjectiveStatus = "unverified-source-field" }
quests[13254] = { id = 13254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Anub'arak", description = "The Scourged nerubians are a plague upon our forces.\n\nWhile we are safe from them here, floating above the world, when we set foot upon the land below, it is always with the thought that the undead nerubians could burrow up from the depths of Azjol-Nerub and attack.\n\nIt's in the best interests of everyone if they are thrown into a state of disarray. Kill their former king, and major-domo to the Lich King, the crypt lord, Anub'arak.\n\nPlease bring me his crown... not that he wears it any longer.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Idle Crown of Anub'arak.\n\nThis quest may only be completed on Heroic difficulty.", progress = "I'm glad that it's you going down into Azjol-Nerub and not myself.\n\nI do not like being under the world.", completion = "What horrors you must have faced while traversing the Upper City.\n\n<Lan'dalock glances down at the tarnished crown clutched in your fist.>\n\nPerhaps we should put that aside for their new king whenever the nerubians decide to coronate one?", sourceObjectiveStatus = "unverified-source-field" }
quests[13255] = { id = 13255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Herald Volazj", description = "The nerubians of Ahn'kahet dug too deep during their attempt to escape the invasion of the Scourge. They got too close to the Old God under Northrend.\n\nRousing its awareness, the Old God sent its insane creatures against them, and the nerubians were caught between the proverbial rock and a hard place.\n\nThe leader of the Old Gods' forces, Herald Volazj is one of the nightmarish beings known as The Faceless. Put an end to him and bring me his withered brain.\n\nJust please, try to keep your sanity.", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Faceless One's Withered Brain.\n\nThis quest may only be completed on Heroic difficulty.", progress = "{name}? Are you still sane?", completion = "<The archmage eyes the brain warily.>\n\nNow that I think of it, I'm not quite sure that it's safe to be so near to that thing. You say that it's still alive?\n\n<He shakes his head.>\n\nWe have a place for such things in the citadel. I'll see to it that one of my apprentices takes it there straight away.", sourceObjectiveStatus = "unverified-source-field" }
quests[13256] = { id = 13256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Demise: Cyanigosa", description = "We're being invaded! The blue dragonflight has teleported into the Violet Hold and they're planning on breaking out from there into the rest of Dalaran!\n\nThere have already been reports of prisoners inadvertently being freed by their actions. It wouldn't surprise me if they're purposefully letting some of them free.\n\n{name}, can you assemble your team quickly and get in there? Cyanigosa is the leader of their invasion force. Bring me her head!", sourceObjective = "Archmage Lan'dalock in Dalaran wants you to return with the Head of Cyanigosa.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Come to think of it, why would you ever teleport into a prison to break out of it? It's only the most secure place in the city.\n\nI think the blues must have truly gone insane!", completion = "The danger is over and the rest of the prisoners that had broken free are being imprisoned once more.\n\nDalaran owes you a debt of gratitude, {name}!\n\nNow I need to go speak with someone about why it was so easy to bypass the city's anti-teleportation protections within the prison?!", sourceObjectiveStatus = "unverified-source-field" }
quests[13257] = { id = 13257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herald of War", description = "The Warchief needs you, champion. Orgrimmar is in a state of martial law. All merchants and services have been shut down as the Warchief prepares for an unavoidable conflict.\n\nI cannot tell you much more - not now. Not in this place.\n\nThe Warchief commands that our strongest champions report to his throne room. Go now, {name}! Take the portal back to Orgrimmar and seek out Thrall.", sourceObjective = "Report to Thrall at Grommash Hold in Orgrimmar.", completion = "The demon lord, Varimathras, and the Forsaken's chief apothecary, Putress, are responsible for this betrayal.\n\n<Thrall nods.>\n\nYes, the same Putress responsible for discovering the cure for the recent Scourge plague outbreak.\n\nThose that would not side with their regime have been executed or banished. Sylvanas was nearly killed in the coup.\n\nThe Horde has lost the Undercity. Orgrimmar will take on the Forsaken refugees until there is a resolution to this crisis. For now we are under martial law.", sourceObjectiveStatus = "unverified-source-field" }
quests[13258] = { id = 13258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opportunity", description = "We recently came upon schematics that indicate a weakness in Icecrown Citadel.  An opening in its defenses, both figuratively and literally.\n\nThe captured diagrams show an orifice leading several hundred feet into the ground.  We're unsure of its purpose, but our scouting has revealed it to be of high importance to the Scourge.\n\nSpeak to Sergeant Kregga below Icecrown Citadel, she's leading the attack on the site.", sourceObjective = "Speak to Sergeant Kregga below Icecrown Citadel.", completion = "Just in time, {name}.  Koltira spoke highly of you.  Perhaps you'll be able to push the scales in our favor.", sourceObjectiveStatus = "unverified-source-field" }
quests[13259] = { id = 13259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Establishing Superiority", description = "We've one shot at dealing some damage to this place -- let's make sure we get it right.\n\nWe've acquired potent, Scourge-made, saronite bombs.  But we must secure this area before we can set them off.\n\nWe're going to need to get the Scourge defenses under control quickly, before reinforcements arrive.\n\nHelp my men out and come back when you're ready for some fireworks.", sourceObjective = "Sergeant Kregga at Icecrown Citadel wants you to slay 10 Hulking Horrors.", progress = "For honor, {name}.", completion = "You made quick work of the Scourge, {name}.  Let's finish what we came to do here.", sourceObjectiveStatus = "unverified-source-field" }
quests[13260] = { id = 13260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Takes One to Know One", description = "While we should never miss an opportunity to strike out against the Alliance, we mustn't forget about the Scourge.\n\nWe won't have the numbers here to make a proper assault in the glacier for weeks, but that won't keep us from learning all we can know about their defenses.\n\nI have asked our resident death knight to advise you in this effort. After all, who better knows this enemy than they?\n\nAllow me to introduce Koltira Deathweaver.", sourceObjective = "Sky-Reaver Korm wants you to speak to Koltira Deathweaver on Orgrim's Hammer.", completion = "<Koltira looks you up and down.>\n\nI hope for your sake that you're up to this, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13261] = { id = 13261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volatility", description = "Wahooo! It works! Not that I had any doubts in my supernatural ingenuity, only that I wasn't quite sure what kind of explosion to expect - let's just say I'm glad to see that you didn't get your eyebrows singed off. So now I just need to show ol' Korm how ya thaw out one 'a them wyrms. He'll hafta promote me to... to... to whatever comes after Chief Engineer! Here, you take another batch of the stuff and head back out to the front and I'll go get Korm...\n\nWell? Move out!", sourceObjective = "Chief Engineer Copperclaw wants you to use Copperclaw's Volatile Oil at the Broken Front to attract 3 Frostbrood Skytalons.\n\nTo use the oil, you must collect a Pile of Bones, an Abandoned Helm, and Abandoned Armor from the battlefield there.", completion = "No good!\n\nKorm kept telling me he was too busy and when I finally got him to come topside and have a look, you had already used the last of the oil. Now he's ticked at me and won't even allow me in his presence again until tomorrow...\n\nCome back then and we'll try again!", sourceObjectiveStatus = "unverified-source-field" }
quests[13262] = { id = 13262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blow it Up!", description = "This is probably as under-control as this situation is going to get.  Let's do this, {name}.\n\nI need someone to light the fuse on those bombs and it looks like you're the one to do it.", sourceObjective = "Go to the nearby Saronite Bomb Stack to light the fuse.", completion = "These bombs look pretty potent.  They should at least put a dent in the surrounding structure.", sourceObjectiveStatus = "unverified-source-field" }
quests[13263] = { id = 13263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Short Fuse", description = "As you light the fuse, you notice that it is consumed by fire far quicker than you would expect.\n\nThe bombs are about to go off and your best chance at surviving is to lean towards the pit and hope the fall doesn't kill you.", sourceObjective = "Look for clues wherever the fall takes you.", completion = "This pulsing object is covered in a thick layer of ice.  It shimmers strangely beneath the water.", sourceObjectiveStatus = "unverified-source-field" }
quests[13264] = { id = 13264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Abominable!", description = "Abominations...\n\nThey can be a very capable enemy. I've seen them turn the tide of battle more than once. What few realize, is that they can also be very capable friends.\n\nThey are not deep thinkers. If you know the secrets of their creation, you can issue them basic orders that they will not question.\n\nFortunately for you, I know these secrets.\n\nThis kit will reanimate the remains of the abominations you defeat. Take it, and learn to use them against the Scourge on the death gate.", sourceObjective = "Koltira Deathweaver on Orgrim's Hammer wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers.", completion = "You see, {class}?\n\nIngenuity can sometimes even the odds against a seemingly overwhelming enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[13265] = { id = 13265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloth Scavenging", progress = "The cut of your clothes suggests to me that you are a Tailor yourself and could easily learn the skill that I have to teach.\n\nMany of the northern humanoids wear clothes that can quickly be converted into cloth if you know the knack of doing it.\n\nFor a small fee I can teach you the art of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", completion = "Turn that extra cloth you find into something that looks marvelous!" }
quests[13266] = { id = 13266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Life Without Regret", description = "On the day of my death I wish to be able to say that I lived a life without regret. Those who mourn my passing will know that I was a Warchief who made decisions that best served his people.\n\nBut this betrayal by Varimathras and Putress... All that we have worked for is for nothing.\n\n<Thrall's chest heaves with a heavy sigh.>\n\nJustice must be served.\n\nPortals to Undercity will be active momentarily. Vol'jin will be waiting for you. I will meet you there soon. Together we will make it right, {name}.", sourceObjective = "Take the portal to Undercity located in Grommash Hold and report to Vol'jin.", completion = "Let me get you up to speed, {name}.\n\nUndercity is a war-zone. Putress' apothecaries and Varimathras' demons have seized control. They've taken a defensive position inside and are using that damned blight against our troops.", sourceObjectiveStatus = "unverified-source-field" }
quests[13267] = { id = 13267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle For The Undercity", description = "The entirety of the Undercity is controlled by Varimathras. Our soldiers stand ready, waiting for the Warchief to give the attack orders.\n\nHelp the Horde take back the Undercity and earn your place among our greatest champions! Should you survive the assault, report to Thrall.\n\nCheck in with the Warchief when you are ready to begin.", sourceObjective = "Assist Thrall and Sylvanas in retaking the Undercity for the Horde.\n\nReport to Thrall should you succeed.", completion = "Tomorrow brings with it uncertainty. Gone are the days of Alliance and Horde battling alongside each other in pursuit of a common enemy. A new battle dawns, {name} - a battle in which there can be no victor.\n\nBut we must continue our march towards Icecrown. We have no choice in that matter. Our salvation lies with heroes like you, {name}. The future of the Horde - of the world - depends on you.\n\nLet us return to Orgrimmar. You must return to Northrend at once.", sourceObjectiveStatus = "unverified-source-field" }
quests[13268] = { id = 13268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloth Scavenging", progress = "You look like someone who knows their way around a needle and thread so maybe I can help you.\n\nThe northern humanoids wear clothes that can quickly be converted into cloth if you know how.\n\nFor a few gold I am willing to teach you the art of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", completion = "Come back when you have the skill and I can provide all of your tailoring training." }
quests[13269] = { id = 13269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloth Scavenging", progress = "The humanoids of the northern lands wear garments that can be converted into cloth if you know how.\n\nFor a few gold I am willing to teach you the art of Cloth Scavenging that will give you additional frostweave cloth from the humanoids of Northrend that you slay.", completion = "May you slay many humanoids and take their cloth." }
quests[13270] = { id = 13270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloth Scavenging", progress = "You be looking like da type who be knowin' how to sew some threads and so I got somethin' for ya.\n\nDa humanoids of da north be wearin' tings dat can be changed into cloth if you be knowin' da trick of it.\n\nIf you been willin' to part with some cash I can teach you da skill of Cloth Scavenging that be givin' ya extra frostweave cloth from the humanoids of Northrend.", completion = "I be appreciatin' your business." }
quests[13271] = { id = 13271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Voice in the Dark", description = "The object is not a crystal at all, but some form of organ, encased in ice.\n\nAs you touch it, your hand reels in horrible pain.  You feel as if your hand has been cut, yet there is no visible wound.\n\nAs you collect your thoughts, you hear a young boy's voice nearby.\n\n\"You really shouldn't have done that.\"", sourceObjective = "Investigate the nearby voice in Naz'anak, the Forgotten Depths.", completion = "I saw him get rid of it, you know?  He threw it all the way down here.\n\nSaid he wouldn't need it anymore.  Said it made him weak.", sourceObjectiveStatus = "unverified-source-field" }
quests[13272] = { id = 13272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloth Scavenging", progress = "As a Tailor I think you are ready to learn what I have to teach.\n\nMany of the northern humanoids wear clothes that can quickly be converted into cloth if you have the proper skill.\n\nFor a couple of gold coins I can teach you the skill of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", completion = "I think you will find this skill helps you a great deal on your path to tailoring greatness!" }
quests[13273] = { id = 13273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going After the Core", description = "With Norgannon's Shell in hand, only half of the archive key remains to be found. Luckily, I've had the Explorers' League hard at work chasing down leads about the whereabouts of Norgannon's Core.\n\nFar to the southeast of the Inventor's Library, on the slopes to the north of Dun Niffelem, is a camp bearing my name. The Explorers' League representatives seeking the second half of the key are based there. Bring me the maps and the notes they've made and we should be able to track down the other key half.", sourceObjective = "Find Prospector Khrona's Notes and Prospector Soren's Maps at Brann's Base-Camp.", progress = "Have you recovered those notes?", completion = "Ruined? What d'you mean, the camp's been ruined?\n\n<Brann clenches his fists in anger.>\n\nThose iron dwarves will pay for this! There's little we can do now, and we have to focus on finishing the key. But once I get into the halls of Ulduar, the irons and their masters will answer for what they've done!", sourceObjectiveStatus = "unverified-source-field" }
quests[13274] = { id = 13274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Core's Keeper", description = "Prospector Soren's notes say that Norgannon's Core is in the keeping of a sentinel named Athan, one of Mimir's creations.\n\nSoren says the vault where Athan resides is called \"Loken's Bargain\" these days.\n\nLoken, eh? The earthen have mentioned him.\n\nThe vault is said to be southwest of the ruined Explorers' League camp, with a round entrance on a mountainside overlooking the Valley of Ancient Winters.\n\nFind this Athan and get the core from him, but I wouldn't be surprised if you were in for a fight.", sourceObjective = "Obtain Norgannon's Core.", progress = "Was Prospector Soren right? Did you finally find Norgannon's Core?", completion = "This is really it! The key is almost within our grasp. All we need now is a way to combine the shell and the core into a single key. Let's see what Prospector Soren had to say about this...", sourceObjectiveStatus = "unverified-source-field" }
quests[13275] = { id = 13275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time to Hide", description = "You shouldn't have touched it.  But now that you did, he's going to come looking for you.\n\nAnd he'll find you.  Unless you hide yourself from him.\n\nBring me blood from the faceless ones if you want to live!", sourceObjective = "Matthias Lehner wants you to obtain 3 Faceless One's Blood.", progress = "Did you get the blood?", completion = "What are you waiting for?  You have to rub it on you!\n\nQuick!  Or he'll see you!", sourceObjectiveStatus = "unverified-source-field" }
quests[13276] = { id = 13276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Abominable!", description = "You know what to do, {class}.\n\nTake this kit and use the guts from their abominations to create one of your own, then command it to attack the enemy forces at the gate.\n\nYou would do well to refine this tactic for when we make our assault on the gate.", sourceObjective = "Koltira Deathweaver on Orgrim's Hammer wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers.", completion = "I see your skills with the abominations are developing nicely.\n\nBe diligent, friend, and soon the gate will belong to the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13277] = { id = 13277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against the Giants", description = "While it's going to be crucial to defeat the Scourge on the ground, we mustn't neglect the gate itself.\n\nThe flesh giants on the ramparts are capable of hurling massive boulders and chunks of ice, inflicting devastating damage to enemy infantry below.\n\nMuster a force and defeat these giants. We need to know just what we're up against in terms of their strength.\n\nOh... and bring me their spines. If memory serves, there's a little trick I can share with you.", sourceObjective = "Koltira Deathweaver on Orgrim's Hammer wants you to bring him 5 Pustulant Spines from the Pustulant Horrors on Mord'rethar.", progress = "Any success against the giants, {race}?", completion = "Excellent. These look to be usable samples.\n\nTime again to use the enemy's strength against them....", sourceObjectiveStatus = "unverified-source-field" }
quests[13278] = { id = 13278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coprous the Defiled", description = "Reports of a powerful zombie at the death gate have reached my ears, {class}.\n\nWe cannot allow a potential threat such as this to go unchallenged. Any information you are able to glean from engaging it will be better than what we know now.\n\nGo to the western chamber of the gate and find this creature. Fight him, and find a weakness we might exploit.", sourceObjective = "Koltira Deathweaver aboard Orgrim's Hammer wants you to kill Coprous the Defiled at Mord'rethar.", completion = "Well done, {class}.\n\nPerhaps with some investigation, we can discover how they are bringing such a creature into existence.", sourceObjectiveStatus = "unverified-source-field" }
quests[13279] = { id = 13279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basic Chemistry", description = "<Koltira takes the pustulant spines and drains their fluid into a flask.>\n\nA little-known quality of the flesh giants...\n\nTheir spinal fluid interacts with the plague in a very interesting way, turning it into a corrosive acid.\n\nPoured from the towering ramparts, acid may not be a welcome sight to the troops below, but at least the victims won't rise up and add to the enemy's numbers.\n\nPour the contents of this flask into one of the plague cauldrons in the western chamber of the death gate.", sourceObjective = "Koltira Deathweaver aboard Orgrim's Hammer wants you to use Pustulant Spinal Fluid on a plague cauldron at Mord'rethar.", completion = "You have done well, {class}.\n\nWhen our armies arrive to march on the Citadel, we will have a solid plan in place for taking the death gate.", sourceObjectiveStatus = "unverified-source-field" }
quests[13280] = { id = 13280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King of the Mountain", description = "You've just got to get my jumpbot to the tippy top of the mountain to the northwest here at Ymirheim pronto, {name}!\n\nThat dastardly, no-good Blast Thunderbomb is working on his own bot, and I'm afraid he almost has it completed. We're in a race to see who's gonna be king of the mountain!\n\nOnce you jump up there, plant our battle standard in the pile of bones and show everyone that the Alliance, and my engineering skills, are the best!", sourceObjective = "Frazzle Geargrinder in Ymirheim wants you to use her Geargrinder's Jumpbot to plant the Alliance Battle Standard in the skulls at the top of the mountain.", progress = "Hold on a second... you haven't planted our battle standard yet!\n\nWhat's the hold up?", completion = "YOU DID IT! YOU DID IT!\n\n<Frazzle jumps and gives you a big hug.>\n\nOh, you're just my favorite hero ever!\n\nYou think you could come back again tomorrow?", sourceObjectiveStatus = "unverified-source-field" }
quests[13281] = { id = 13281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neutralizing the Plague", description = "You no longer need my assistance in neutralizing the enemy's plague cauldrons, {race}.\n\nHunt down the flesh giants at the death gate and use the fluid from their spines to render batches of the plague ineffective.\n\nYou are striking at the heart of the enemy's strategy. This is an important mission - vital to our cause, and should be carried out whenever time permits.\n\nRemember, the giants and the plague cauldrons can be found on Mord'rethar.", sourceObjective = "Koltira Deathweaver aboard Orgrim's Hammer wants you use Pustulant Spinal Fluid on a blight cauldron at Mord'rethar.\n\nYou can create Pustulant Spinal Fluid by using a Giant Spine collected from a Pustulant Horror.", completion = "One less plague cauldron to account for when the battle commences.\n\nYour commander will be pleased.", sourceObjectiveStatus = "unverified-source-field" }
quests[13282] = { id = 13282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Surface", description = "You should leave now.  You'll find a portal behind me.  It'll take you to the surface.\n\nWe'll meet again.  He'll be looking for you.\n\nIt's only a matter of time until he finds you.", sourceObjective = "Return to Koltira Deathweaver aboard Orgrim's Hammer.", completion = "{name}!  We thought you were dead!\n\nWe lost a few men in that explosion... but we sure put a hurt on the Scourge.  They're scrambling their forces back to the citadel and leaving big gaps in their defenses.  It's time to push forward.", sourceObjectiveStatus = "unverified-source-field" }
quests[13283] = { id = 13283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King of the Mountain", description = "Yo, {name}, I need you to get my jumpbot to the top of this mountain to the southeast, like yesterday!\n\nThat girly, self-righteous Frazzle Geargrinder thinks that her jumpbot's better than mine. Hah! We're in a race to see who's gonna be king of the mountain!\n\nOnce you jump up there, plant our battle standard in the pile of bones and show everyone that the Horde, and my mad engineering skills, are the best!", sourceObjective = "Blast Thunderbomb in Ymirheim wants you to use his Thunderbomb's Jumpbot to plant the Horde Battle Standard in the skulls at the top of the mountain.", progress = "Hold on a second... you haven't planted our battle standard yet!\n\nWhat gives?", completion = "I knew you were the right {race} for the job!\n\n\n\nI gotta admit that right now you're my favorite {class} of all time!\n\nWhat do you say to a repeat performance again tomorrow? I can make it worth your while!", sourceObjectiveStatus = "unverified-source-field" }
quests[13284] = { id = 13284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault by Ground", description = "Greetings {class}.\n\nOur troops have been attempting to storm Ymirheim for some time, but these vrykul are far more vicious than any we've faced before. They've been ambushing us repeatedly as we try to make it up the pass, and we've lost a lot of men.\n\nIf you want to lend yourself to the battle and help get my squad to the gates of Ymirheim safely, we will gladly reward you for your efforts. Once at the gates, we'll dig in and wait for reinforcements to catch up to us.", sourceObjective = "Escort the Skybreaker troops to the gates of Ymirheim. Return to Ground Commander Koup at the edge of the glacier east of Ymirheim for compensation after the task is complete.", progress = "Did you get some of my men up safely?", completion = "You have my thanks.\n\nThis has been a brutal operation, but we haven't had any great options otherwise - they're being equally as unforgiving to our aerial assault. We need to rout these vrykul if we're going to stand any chance of pressing on in Icecrown.\n\nWe're likely to need more help later. Please lend yourself to the battle again should the chance present itself.", sourceObjectiveStatus = "unverified-source-field" }
quests[13285] = { id = 13285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging the Keystone", description = "Aha! Here it is: the Temple of Invention, the seat of Keeper Mimir himself! Of course, that's where one would go to join the two parts of the key.\n\nAccording to the prospector's notes, the Temple of Invention is one of the highest points on the western side of the Terrace of the Makers. That means it should be roughly east of your Grom'arsh Crash Site.\n\nI'll meet you at the temple and we'll combine the parts together.", sourceObjective = "Brann Bronzebeard wants you to meet him at the Temple of Invention and help him combine Norgannon's Shell and Norgannon's Core. Once you have helped Brann, report back to Boktar Bloodfury at the Grom'arsh Crash-Site.", progress = "Do you have the completed keystone?", completion = "<Boktar nods in approval as you tell him how you helped Brann recover the pieces of the keystone and combine them.>\n\nBrann may prove to be just the ally we need to discover what is truly happening in Ulduar. You've done well in aiding him. We need all the help we can get against this Loken and his iron dwarf minions.", sourceObjectiveStatus = "unverified-source-field" }
quests[13286] = { id = 13286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...All the Help We Can Get.", description = "Desperate times, {class}...\n\nAs uncomfortable as it makes me, I'm prepared to accept assistance from anyone - including our resident death knight.\n\nGo to Thassarian and see if he can help us develop tactics against the Scourge that will ensure victory once we are able to mount another offensive.\n\nWe have come so far... we must not fail here!", sourceObjective = "High Captain Justin Bartlett aboard the Skybreaker wants you to speak to Thassarian.", completion = "It was wise of Captain Bartlett to send you.\n\nWhile he frets over your conflict with the Horde, someone must remain exclusively focused on the real mission here - the march on Icecrown Citadel.\n\nWho better to direct your efforts than a former servant of the Lich King?", sourceObjectiveStatus = "unverified-source-field" }
quests[13287] = { id = 13287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poke and Prod", description = "As someone of your experience must surely know, there's no better way to familiarize one's self with their enemy than by confronting them in combat.\n\nWhile you no doubt lust for the glory of taking Icecrown Citadel, that cannot happen without taking each of the Lich King's gates first. For now, you must focus your efforts on the first of these...\n\nReturn to the Broken Front. Engage the enemy in battle. Search for a weakness we might exploit and return to me with a detailed report.", sourceObjective = "Thassarian on the Alliance gunship, Skybreaker, wants you to kill 5 Hulking Abominations, 5 Malefic Necromancers, and 5 Shadow Adepts at the Broken Front.", progress = "You've returned, {class}...\n\nAnything to report?", completion = "Really, {class}?\n\nNothing notable to report?\n\n\n\nI beg to differ...", sourceObjectiveStatus = "unverified-source-field" }
quests[13288] = { id = 13288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Abominable!", description = "Abominations...\n\nThey can be a very capable enemy. I've seen them turn the tide of battle more than once. What few realize, is that they can also be very capable friends.\n\nThey are not deep thinkers. If you know the secrets of their creation, you can issue them basic orders that they will not question.\n\nFortunately for you, I know these secrets.\n\nThis kit will reanimate the remains of the abominations you defeat. Take it, and learn to use them against the Scourge on the death gate.", sourceObjective = "Thassarian on the Skybreaker wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers.", progress = "Well, {race}?\n\nDid your abomination friends prove effective?", completion = "You see, {class}?\n\nIngenuity can sometimes even the odds against a seemingly overwhelming enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[13289] = { id = 13289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Abominable!", description = "You know what to do, {class}.\n\nTake this kit and use the guts from their abominations to create one of your own, then command it to attack the enemy forces at the gate.\n\nYou would do well to refine this tactic for when we make another assault on the gate.", sourceObjective = "Thassarian on the Skybreaker wants you to use the Abomination Reanimation Kit to create a Reanimated Abomination, which you are to use to kill 15 Icy Ghouls, 15 Vicious Geists, and 15 Risen Alliance Soldiers.", completion = "I see your skills with the abominations are developing nicely.\n\nBe diligent, friend, and soon the death gate will belong to the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[13290] = { id = 13290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Attention, Please", description = "Chief Engineer Boltwrench has proven invaluable in his service aboard the Stormbreaker. Were it not for his ingenuity, we'd be sprinkled across half of the glacier several times over by now.\n\nThe thing is, he feels he must share his every miniscule invention or discovery - most of which I don't even understand.\n\nMy focus must be squarely on our enemies right now. I cannot afford any distractions.\n\nPlease visit him in my stead, {name}. And if you can, assist him. You'll find him belowdecks.", sourceObjective = "High Captain Bartlett wants you to speak with Chief Engineer Boltwrench in the Skybreaker.", completion = "Cappy sent you in his place, did he?\n\nVery well, {class}. Roll up those sleeves... time to get to work!", sourceObjectiveStatus = "unverified-source-field" }
quests[13291] = { id = 13291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Borrowed Technology", description = "I get it, I get it. Cappy's too busy to see this for himself. His loss!\n\nSee, I've managed to 'acquire' a certain shipment of solution from the enemy. And as much as I hate tinkerin' with inferior goblin technology, I'm inclined to make an exception here.\n\nTake this sample. I'll need you to run a few field tests, just to prove its usefulness, while I try to do a little reverse engineering to duplicate the creation process.\n\nGo to the front and gather the materials to make a decoy, then use the oil.", sourceObjective = "Chief Engineer Boltwrench aboard the Skybreaker wants you to use the Smuggled Solution at the Broken Front.\n\nUsing the solution will require an Abandoned Helm, Abandoned Armor, and Pile of Bones, all found at the Broken Front.", completion = "Good news!\n\nI've managed to reproduce the solution - hardly an accomplishment, of course.\n\nDoubt I'll live to see the day those neanderthal goblins cook up somethin' a gnome can't recreate in his sleep!", sourceObjectiveStatus = "unverified-source-field" }
quests[13292] = { id = 13292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Solution Solution", description = "Oh, yes, yes. Back again, are we? Never enough practice, I suppose.\n\nHere we are, the solution to that pesky frostwyrm problem.\n\nMake them scarce, {race}. The more you take out now, the less we face when we are again ready to attempt our march on the citadel.\n\nBest of luck, now. And do bring back whatever you don't use.", sourceObjective = "Chief Engineer Boltwrench aboard the Skybreaker wants you to use the Smuggled Solution at the Broken Front.\n\nUsing the solution will require an Abandoned Helm, Abandoned Armor, and Pile of Bones, all found at the Broken Front.", progress = "Yes, friend?", completion = "Good show! Good show indeed. You're turning into a regular wyrmslayer!\n\nCome back when you're ready to thin their numbers even further.", sourceObjectiveStatus = "unverified-source-field" }
quests[13293] = { id = 13293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get to Ymirheim!", description = "You need to get down to Ymirheim, that big frost vrykul town in the middle of Icecrown.\n\nOur boy, Blast Thunderbomb, is down there on the west side of town representing the Warsong Offensive in a competition against the Alliance. It's his jumpbot versus theirs in a king of the mountain contest!\n\nDon't let us down, {name}. Goblin engineering pride is on the line! Besides, all the boys here in the hold are counting on you.\n\nThat and we've got money riding on it that you can kick those cowards in the pants!", sourceObjective = "Speak with Blast Thunderbomb in Ymirheim.", completion = "Oh man, am I glad to see you! Did the chief send you down from the Hammer?", sourceObjectiveStatus = "unverified-source-field" }
quests[13294] = { id = 13294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against the Giants", description = "While it's going to be crucial to defeat the Scourge on the ground, we mustn't neglect the gate itself.\n\nThe flesh giants on the ramparts are capable of hurling massive boulders and chunks of ice, inflicting devastating damage to enemy infantry below.\n\nMuster a force and defeat these giants. We need to know just what we're up against in terms of their strength.\n\nOh... and bring me their spines. If memory serves, there's a little trick I can share with you.", sourceObjective = "Thassarian on the Skybreaker wants you to bring him 5 Pustulant Spines from the Pustulant Horrors on Mord'rethar.", progress = "Any success against the giants, {race}?", completion = "Excellent. These look to be usable samples.\n\nTime again to use the enemy's strength against them....", sourceObjectiveStatus = "unverified-source-field" }
quests[13295] = { id = 13295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basic Chemistry", description = "<Thassarian takes the pustulant spines and drains their fluid into a flask.>\n\nA little-known quality of the flesh giants...\n\nTheir spinal fluid interacts with the plague in a very interesting way, turning it into a corrosive acid.\n\nPoured from the towering ramparts, acid may not be a welcome sight to the troops below, but at least the victims won't rise up and add to the enemy's numbers.\n\nPour the contents of this flask into one of the plague cauldrons in the western chamber of the death gate.", sourceObjective = "Thassarian aboard the Skybreaker wants you to use Pustulant Spinal Fluid on a plague cauldron at Mord'rethar.", completion = "You have done well, {class}.\n\nWhen our armies arrive to march on the Citadel, we will have a solid plan in place for taking the death gate.", sourceObjectiveStatus = "unverified-source-field" }
quests[13296] = { id = 13296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get to Ymirheim!", description = "I need you down in Ymirheim, that big frost vrykul town in the middle of Icecrown.\n\nFrazzle Geargrinder is down there on the south side of town representing the Valiance Expedition in a competition against the Horde scum. It's her jumpbot versus theirs in a king of the mountain contest!\n\nDon't let us down, {name}. Gnomish engineering pride is on the line! Besides, all the boys here in the hold are counting on you.\n\nThat and we've got money riding on it that you can kick those idiots in the pants!", sourceObjective = "Speak with Frazzle Geargrinder in Ymirheim.", completion = "Did the chief send you down from the Skybreaker? Isn't that thing sweet?!", sourceObjectiveStatus = "unverified-source-field" }
quests[13297] = { id = 13297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neutralizing the Plague", description = "You no longer need my assistance in neutralizing the enemy's plague cauldrons, {race}.\n\nHunt down the flesh giants at the death gate and use the fluid from their spines to render batches of the plague ineffective.\n\nYou are striking at the heart of the enemy's strategy. This is an important mission - vital to our cause, and should be carried out whenever time permits.\n\nRemember, the giants and the plague cauldrons can be found on Mord'rethar.", sourceObjective = "Thassarian aboard the Skybreaker wants you use Pustulant Spinal Fluid on a plague cauldron at Mord'rethar.\n\nYou can create Pustulant Spinal Fluid by using a Giant Spine collected from a Pustulant Horror.", completion = "One less plague cauldron to account for when the battle commences.\n\nYour captain will be highly pleased.", sourceObjectiveStatus = "unverified-source-field" }
quests[13298] = { id = 13298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coprous the Defiled", description = "Reports of a powerful zombie at the death gate have reached my ears, {class}.\n\nWe cannot allow a potential threat such as this to go unchallenged. Any information you are able to glean from engaging it will be better than what we know now.\n\nGo to the western chamber of the gate and find this creature. Fight him, and find a weakness we might exploit.", sourceObjective = "Thassarian aboard the Skybreaker wants you to kill Coprous the Defiled at Mord'rethar.", completion = "Well done, {class}.\n\nPerhaps with some investigation, we can discover how they are bringing such a creature into existence.", sourceObjectiveStatus = "unverified-source-field" }
quests[13299] = { id = 13299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ZZOLDWisp Cloak" }
quests[13300] = { id = 13300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaves to Saronite", description = "Our people are being captured and put to work as slaves in the saronite mines of Ymirheim, the vrykul stronghold in the middle of Icecrown. The Lich King has them mining that unholy ore day and night.\n\nI made a promise to Highlord Fordring that we would get those wretches out of there alive, and that's exactly what we will do.\n\nUnfortunately, I've been ordered to stay on this gunship and serve as an ambassador to the Valiance Expedition. Will you please rescue them in my stead, {name}?", sourceObjective = "Absalan the Pious aboard the Skybreaker wants you to rescue 10 Saronite Mine Slaves.", completion = "They're being driven insane? Voices in their heads?\n\nVoices in your head?!\n\nI want you to clear your mind of the taint that has crept into that place, boy.\n\nWe'll try to get the remainder of them out of there again tomorrow when you've had a chance to rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[13301] = { id = 13301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault by Ground", description = "Greetings {class}.\n\nOur troops have been attempting to storm Ymirheim for some time, but these vrykul are far more vicious than any we've faced before. They've been ambushing us repeatedly as we try to make it up the pass, and we've lost a lot of men.\n\nIf you want to lend yourself to the battle and help get my squad to the gates of Ymirheim safely, we will gladly reward you for your efforts. Once at the gates, we'll dig in and wait for reinforcements to catch up to us.", sourceObjective = "Escort the Kor'kron troops to the gates of Ymirheim. Return to Ground Commander Xutjja at the edge of the glacier north of Ymirheim for compensation after the task is complete.", progress = "Did you get some of my men up safely?", completion = "You have my thanks.\n\nThis has been a brutal operation, but we haven't had any great options otherwise - they're being equally as unforgiving to our aerial assault. We need to rout these vrykul if we're going to stand any chance of pressing on in Icecrown.\n\nWe're likely to need more help later. Please lend yourself to the battle again should the chance present itself.", sourceObjectiveStatus = "unverified-source-field" }
quests[13302] = { id = 13302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaves to Saronite", description = "Our people are being captured and put to work as slaves in the saronite mines of Ymirheim, the vrykul stronghold in the middle of Icecrown. The Lich King has them mining that unholy ore day and night.\n\nI made a promise to Highlord Fordring that we would get those wretches out of there alive, and that's exactly what we will do.\n\nUnfortunately, I've been ordered to stay on this gunship and serve as an ambassador to the Warsong Offensive. Will you please rescue them in my stead, {name}?", sourceObjective = "Brother Keltan aboard Orgrim's Hammer wants you to rescue 10 Saronite Mine Slaves.", completion = "They're being driven insane? Voices in their heads?\n\nVoices in your head?!\n\nI want you to clear your mind of the taint that has crept into that place, boy.\n\nWe'll try to get the remainder of them out of there again tomorrow when you've had a chance to rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[13304] = { id = 13304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Repairs", description = "The Scourge is still reeling from our attack, {name}.  Now is the time to capitalize on our momentum.\n\nThe strategically important valley below us is wide open.  We've located a disassembled demolisher vehicle in what we believe is working condition in the southeastern corner of the Valley of Lost Hope area.\n\nIf you can get the remaining parts from the Scourge scavengers, you should be able to get it running again.  A single working demolisher can wreak havoc on the enemy's ground units.", sourceObjective = "Koltira Deathweaver aboard Orgrim's Hammer wants you to collect 5 Demolisher Parts from the Scavenging Geists in the Valley of Lost Hope and take them to the Wrecked Demolisher.", progress = "The demolisher has suffered much damage.", completion = "The Demolisher has seen better days, but the structure hasn't suffered any permanent damage.  The parts you obtained should be enough to get it running again, at least temporarily.", sourceObjectiveStatus = "unverified-source-field" }
quests[13305] = { id = 13305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do Your Worst", description = "You're going to use this machine against the Scourge?  You're not going to win against them like that.\n\nYou can destroy hundreds... even thousands of them.  But you won't win.  Not out here.\n\nWhen you're done playing with your machine, meet me to the north.  There is an old army encampment.  What I will show you will teach you a little bit about who you're up against.", sourceObjective = "Use the Refurbished Demolisher to destroy 150 Decomposed Ghouls, 20 Frostskull Mages and 2 Bone Giants in the Valley of Lost Hope. Speak to Matthias Lehner at the First Legion Forward Camp when you've completed this task.", completion = "You see?  You killed your fair share, but for every one you destroyed, another rose from the dirt to take its place.\n\nYou don't know what you're up against, {name}.  Let me show you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13306] = { id = 13306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raise the Barricades", description = "When our forces begin to move beyond Aldur'thar, they will be vulnerable to attack from the Ironwall Rampart and the broad glacier below.\n\nWe have neither the time nor the materials to build fortifications, but we can put up some barricades to shield our men from fire and break up Scourge charges.\n\nTake this barricade kit to the Valley of Fallen Heroes, on the west side of Aldur'thar. Locate the markers I've placed there and use this kit to construct your barricades there.", sourceObjective = "Koltira Deathweaver, aboard Orgrim's Hammer, wants you to construct 8 Barricades using your Barricade Construction Kit.", completion = "<Koltira nods curtly.>\n\nGood. It's not much protection, but it's better than nothing. That gate is still the perfect choke point if the Scourge commanders know what they're doing. We must gain control of as much of the surrounding area as possible.", sourceObjectiveStatus = "unverified-source-field" }
quests[13307] = { id = 13307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodspattered Banners", description = "In the Valley of Fallen Heroes and Icecrown Glacier, to the west of Aldur'thar, the Scourge seeks to use the fallen against us. Scourge lieutenants have woken the valley's dead and imbued them with fearsome strength and fervor. The banners carried by the Scourge leaders in the glacier area are the source of these powers. Kill the banner-bearers, and you will weaken the converted heroes they lead.\n\nIt falls to you to rid us of this obstacle, and thin the resistance before the main body can advance.", sourceObjective = "Koltira Deathweaver, aboard Orgrim's Hammer, wants you to kill 5 Scourge Banner-Bearers, 5 Scourge Converters, and 20 Converted Heroes.", completion = "You have removed the Scourge banner-bearers and their minions? Good. Our preparations must continue.", sourceObjectiveStatus = "unverified-source-field" }
quests[13308] = { id = 13308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mind Tricks", description = "<The creature speaks directly into your mind, its thoughts painful and strange.>\n\n{race}-thing, I am in need of your assistance. Like your enslaved friends, I am a victim of the Lich King's ymirjar and their avarice. When I rose from below to investigate the noises coming from this cavern they captured and chained me.\n\nWill you please help me? The foreman of these mines holds the key to my chains. Kill him!\n\n<You can feel a pushing against your mind as if the creature is trying to coerce you.>", sourceObjective = "Darkspeaker R'khem in the Saronite Mines wants you to recover the Foreman's Key to his chains.", progress = "You will be richly rewarded for your service to me.\n\n<The darkspeaker projects soothing feelings into your mind.>\n\nYou will not regret unfettering me.", completion = "<Another wave of euphoria, mixed with some pain, crashes through your mind as you approach the creature.>\n\nGood... good! So that you know I am being fair, I will first give you your reward as promised.\n\nAnd then you will willingly hand me the key.", sourceObjectiveStatus = "unverified-source-field" }
quests[13309] = { id = 13309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault by Air", description = "I've got some boys suited and ready for their drops inside of Ymirheim. I could use you to see them there safely.\n\nInside the walls, the vrykul have set up some kind of automated spear guns that have been tearing up our transports. We had our engineers install a Suppression Turret to shut down those spear guns - just fire a round near any gun and the smoke should block its sight and clog its gears.\n\nHop on the turret and see to it that all my boys make it to their drops in one piece.", sourceObjective = "Ground Commander Koup at the edge of the glacier east of Ymirheim has ordered you to use the Skybreaker Suppression Turret to keep the Skybreaker Troop Transport alive long enough to make all of its drops.", progress = "Did you get my boys inside?", completion = "Excellent work, soldier. We could use more able bodies like you around here - stop by another day if the operation hasn't wrapped up.", sourceObjectiveStatus = "unverified-source-field" }
quests[13310] = { id = 13310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault by Air", description = "Alright scrub, I've got something to keep you from being a complete waste.\n\nA unit of highly trained infiltrators is ready to be dropped inside of Ymirheim. The vrykul inside have automated spear guns that have been ripping our transports to shreds, so we had the engineers on Orgrim's Hammer whip us up a suppression turret.\n\nYou're the gunner. Launch rounds at their spear guns to obscure their vision and clog their gears. See to it that my men all make their drops and the transport stays in one piece.", sourceObjective = "Ground Commander Xutjja at the edge of the glacier north of Ymirheim has ordered you to use the Kor'kron Suppression Turret to keep the Kor'kron Troop Transport alive long enough to make all of its drops.", progress = "Get the job done?", completion = "Only partly useless then. Good work.", sourceObjectiveStatus = "unverified-source-field" }
quests[13311] = { id = 13311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demons Deck", description = "Now that you have gathered all of the Demon cards together into a deck, another card appears on top.  It depicts a fortune teller that seems to stare at you no matter how you hold the card.\n\nYou feel the card could be used to communicate with someone or something.", sourceObjective = "Use the Demons Deck to summon a Darkmoon Fortune Teller and give the deck to them.", progress = "I see that you have managed to complete a deck of Demons!   Congratulations!", completion = "The tarot cards are of great interest to the Darkmoon Faire, so do not hesitate to call upon us if you manage to collect more.  We are not without our own skilled tradesmen, so please allow us to offer something in return.", sourceObjectiveStatus = "unverified-source-field" }
quests[13312] = { id = 13312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ironwall Rampart", description = "The Ironwall Rampart overlooks the Valley of Fallen Heroes, west of Aldur'thar. The rampart dominates the fields below on all sides. We will not be able to advance if the rampart cannot be taken, but it is held by Grimkor the Wicked and his Cult of the Damned disciples.\n\nIf you can weaken Grimkor, our forces know what to expect as we advance. Take this rune of distortion. Unleashing its power near Grimkor's orb at the end of the rampart should be enough to get the necromancer's attention.", sourceObjective = "Defeat Grimkor the Wicked and return to Koltira Deathweaver aboard Orgrim's Hammer.", completion = "So Grimkor has fallen by your hand? Excellent work. With him out of the way, our chances of taking and holding the rampart during the assault are greatly improved.", sourceObjectiveStatus = "unverified-source-field" }
quests[13313] = { id = 13313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blinding the Eyes in the Sky", description = "The Alliance has somehow managed to field a squadron of recon vehicles over the Valley of Fallen Heroes and Icecrown Glacier, the broad areas west of Aldur'thar.\n\nThey cannot be permitted to take the lead in this fight. Chief Engineer Copperclaw has supplied me with the perfect weapon to deal with this threat -- he calls his new missile the SGM-3. I have his assurances that it will take out the Alliance flying machines in a single hit. Go and use this weapon to give us the upper hand.", sourceObjective = "Use the SGM-3 to destroy 6 Skybreaker Recon Fighters, then report back to Sky-Reaver Korm Blackscar aboard Orgrim's Hammer.", completion = "Good. Fewer Alliance pests to stand in our way. We'll show them what true warriors look like.", sourceObjectiveStatus = "unverified-source-field" }
quests[13314] = { id = 13314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get the Message", description = "The Horde is up to something and I don't like it. After the stunt they pulled on the Broken Front, they're capable of anything, and it's up to us to stop it.\n\nThere's been a flurry of activity in the skies over the Icecrown Glacier, to the west of Aldur'thar and the Ironwall Rampart. Horde scouts and messengers streak in and out on dragonhawks, carrying reports and orders. Take this dart gun and use it to kill the Orgrim's Hammer Scouts. It'll probably work best if you're flying, too.", sourceObjective = "Capture 6 Orgrim's Hammer Dispatches from Orgrim's Hammer Scouts and bring them to High Captain Justin Bartlett aboard the Skybreaker.", progress = "Have you intercepted those dispatches?", completion = "It's good to have someone competent running missions, {name}. If only we had an army of paladins like you, we could show the Horde what we're made of. These captured reports will help us to maintain the upper hand in this fight. We may be down, but we're far from out.", sourceObjectiveStatus = "unverified-source-field" }
quests[13315] = { id = 13315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sneak Preview", description = "Progress is being made. We have a promising array of tactics that should gain us control of the death gate. There will doubtlessly be many casualties, but in the end,  we should be able to prevail - barring any interference from those Horde you insist on contending with...\n\nAt any rate, our next focus will be the gate of desolation. Fly down and become familiar with it and with the enemies posted there.\n\nWhen you return, I will have your missions prepared.", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to fly down to the gate of desolation, visiting the south, central, north, and northwest regions of the gate.", progress = "Have you scouted the gate of desolation, {class}?", completion = "Well and good, {class}.\n\nNow that you've seen firsthand what we're up against, it's time to get to work...", sourceObjectiveStatus = "unverified-source-field" }
quests[13316] = { id = 13316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Guardians of Corp'rethar", description = "Corp'rethar, called the Horror Gate. It is the last barrier between us and the Icecrown Citadel. It waits to the south of the Ironwall Rampart, beyond the glacier and the Conflagration. By the time our troops reach it, they will be exhausted and worse.\n\nWe must weaken its defenses, or our army's strength will break upon its walls.\n\nIts battlements are manned by some of the Lich King's fiercest and most zealous servants. Do all you can to destroy these guardians and hope it is enough.", sourceObjective = "Koltira Deathweaver, aboard Orgrim's Hammer, wants you to kill 5 Harbingers of Horror and 5 Corp'rethar Guardians.", completion = "I hope your success at Corp'rethar will prove an omen of the battle ahead. The Lich King cannot sit idly by as we march to the very gates of his stronghold.", sourceObjectiveStatus = "unverified-source-field" }
quests[13318] = { id = 13318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drag and Drop", description = "The Cult of the Damned hold the gate of desolation, eh? No surprise there.\n\nTime to have a little fun. At the southern end of the gate, you mentioned there were new cultists being trained. They're almost certain to be holding a special item given to all initiates - an Orb of Illusion.\n\nThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.\n\nKill the fools until you find one, {class}, then use it on a subjugator.", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur'thar and use them on 3 Dark Subjugators there.", completion = "An effective tool, given the circumstances, wouldn't you say?\n\nThat one never gets old....", sourceObjectiveStatus = "unverified-source-field" }
quests[13319] = { id = 13319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chain of Command", description = "Based on your report, and my knowledge of the Cult, they have an overseer managing the operation of each encampment on the gate.\n\nWhile taking their leaders down will only be a temporary setback, it will at least slow them down and keep them off-balance. And that, {race}, is a worthy enough goal for now.\n\nSeek out these overseers and return to me when they have been dispatched.", sourceObjective = "Thassarian aboard the Skybreaker wants you to go to Aldur'thar and defeat Overseer Faedris, Overseer Savryn, Overseer Veraj, and Overseer Jhaeqon.", completion = "Well done, {race}. But don't break your arm patting yourself on the back. They'll have those overseers replaced in no time...", sourceObjectiveStatus = "unverified-source-field" }
quests[13320] = { id = 13320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cannot Reproduce", description = "I smell their cauldrons from here, but that's not plague they're cooking.\n\nPledges to the cult are forced to drink a concoction that steals their will and enslaves them forever to the Lich King.\n\nSome say the potion contains the twisted soul of a being who was tormented before being mercilessly slaughtered, but I've never been able to reproduce it...\n\nFill this flask with a sample from each of the three cauldrons in the northwest region of the gate and bring it to Chief Engineer Boltwrench.", sourceObjective = "Thassarian aboard the Skybreaker wants you to use the Partitioned Flask at each of the 3 Cultists' Cauldrons at Aldur'thar, then bring it to Chief Engineer Boltwrench.", progress = "Whatdya got there, {race}?", completion = "<Boltwrench pours the contents of the flask into his tetrahydroparticle analyzer.>\n\nWhat we have here is a simple failure to conglomerate...", sourceObjectiveStatus = "unverified-source-field" }
quests[13321] = { id = 13321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retest Now", description = "This should do the trick!\n\nThose twisted hooligans are looking for souls to put in their crazy-juice? Then I say we help 'em out a bit!\n\nTake a swig of this - don't worry, I've diluted it plenty... I'm almost positive that its only effect will be to detect any cultist's essence once you've defeated them.\n\nWhen you've collected a bunch of them, throw the writhing mass of twisted souls into any of their cauldrons.\n\nLet's see how they like a taste of their own medicine!", sourceObjective = "Chief Engineer Boltwrench aboard the Skybreaker wants you to throw a Writhing Mass into a cauldron at Aldur'thar.", completion = "Wahoo!\n\nThat'll teach 'em!", sourceObjectiveStatus = "unverified-source-field" }
quests[13322] = { id = 13322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retest Now", description = "Those twisted cultists are looking for souls to put in their crazy-juice? Then let's help 'em out a bit!\n\nTake a swig of this - don't worry, I've diluted it plenty... I'm almost positive that its only effect will be to detect any cultist's essence.\n\nOnce you've collected a bunch of 'em, throw the writhing mass of twisted souls in one of their cauldrons.\n\nLet's see how they like a taste of their own medicine!", sourceObjective = "Chief Engineer Boltwrench aboard the Skybreaker wants you to drink the Diluted Cult Tonic, kill any Cultists at Aldur'thar and take their Tainted Essences. You are then to combine 10 of the essences into a Writhing Mass and throw it into any of their cauldrons.", completion = "Wahoo!\n\nThat'll teach 'em!", sourceObjectiveStatus = "unverified-source-field" }
quests[13323] = { id = 13323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drag and Drop", description = "Looks like those initiates are increasing in number again. You know what to do...\n\nAt the southern portion of the gate, the new cultists are being trained. They're certain to be holding a special item given to all initiates - an Orb of Illusion.\n\nThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.\n\nSlay the fools until you find some, then use them on the subjugators there.", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur'thar and use them on 3 Dark Subjugators there.", completion = "An effective tool, given the circumstances, wouldn't you say?\n\nThat one never gets old....", sourceObjectiveStatus = "unverified-source-field" }
quests[13324] = { id = 13324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Prisms Deck", description = "Now that you have gathered all of the Prism cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Prisms Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Prisms!   Congratulations!", completion = "So you have put together a deck of Prisms.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[13325] = { id = 13325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Chaos Deck", description = "Now that you have gathered all of the Chaos cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Chaos Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Chaos!   Congratulations!", completion = "So you have put together a deck of Chaos.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[13326] = { id = 13326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Nobles Deck", description = "Now that you have gathered all of the Nobles cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Nobles Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Nobles!   Congratulations!", completion = "So you have put together a deck of Nobles.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[13327] = { id = 13327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Undeath Deck", description = "Now that you have gathered all of the Undeath cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", sourceObjective = "Return the Undeath Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Undeath!   Congratulations!", completion = "So you have put together a deck of Undeath.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[13328] = { id = 13328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shatter the Shards", description = "Atop the battlements of Corp'rethar, the Lich King's minions have erected three crystals, the shards of horror, despair, and suffering. Should our men reach the walls of Corp'rethar, he will unleash these weapons on our army.\n\nIn full effect, the crystals will afflict the minds of our men with paralyzing pain and fear. Then, the Scourge will be able to slaughter them at will.\n\nFind these shards, destroy them, and bring me their broken remains. We cannot allow the Lich King to deploy these weapons!", sourceObjective = "Bring the Broken Shard of Horror, the Broken Shard of Despair, and the Broken Shard of Suffering to Koltira Deathweaver aboard Orgrim's Hammer.", progress = "Have you shattered the Lich King's new weapons?", completion = "<Koltira takes the crystal shards from you and speaks in a quiet voice.>\n\nI remember these...\n\nLesser men would easily crumble beneath their assault. You have done well in removing their threat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13329] = { id = 13329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Before the Gate of Horror", description = "The Conflagration, the ground before Corp'rethar, south of the Ironwall Rampart, is where the Lich King's elite soldiers have formed up to defend the citadel.\n\nLed by a contingent of death knights, a legion of skeletal reavers bars the way. I fear that even when these reavers fall, the Scourge will simply reconstitute them and send them back at us.\n\nI've come up with a plan to stop this, but I have no way of knowing if it will work. Take this solution and use it to dissolve the remains of the reavers.", sourceObjective = "Koltira Deathweaver, aboard Orgrim's Hammer, wants you to use the Volatile Acid to dissolve the remains of 6 Skeletal Reavers.", completion = "<Koltira listens to your report.>\n\nGood. I'll have the engineers mix up as much of that acid as they can before we prepare to assault Corp'rethar with the main force.", sourceObjectiveStatus = "unverified-source-field" }
quests[13330] = { id = 13330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of the Chosen", description = "Those vrykul that have gained the favor of the Lich King call themselves the Ymirjar. They inhabit a city in the center of Icecrown. We have a lot of preparations to make before we assault Icecrown Citadel, and the one that stands before us now is routing these so-called \"Chosen\" of the Lich King.\n\nGo to their city, Ymirheim, and slaughter them in their home. Let there be no questions as to who the stronger combatants are here.", sourceObjective = "Warbringer Davos Rioht on Orgrim's Hammer has sent you to kill 20 vrykul in Ymirheim.", completion = "Not so strong after all, it seems. The Lich King will get what's coming to him.", sourceObjectiveStatus = "unverified-source-field" }
quests[13331] = { id = 13331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping the Alliance Blind", description = "The Alliance is tenacious, I'll give them that, but it'll take more than that to stop us. Take this SGM-3 with you and shoot down the Skybreaker's recon fighters once again.\n\nI doubt the message will get through their thick skulls, but there are enough missiles to keep trying to get our point across. Go and find their fighters flying above the Valley of Fallen Heroes, west of Aldur'thar, and don't come back until you've made wreckage of them.", sourceObjective = "Use the SGM-3 to destroy 6 Skybreaker Recon Fighters, then report back to Sky-Reaver Korm Blackscar aboard Orgrim's Hammer.", progress = "Have you eliminated the Alliance's reconnaissance operations in the western part of the glacier?", completion = "Well done, once again. Horde superiority is assured, at least until those Alliance pukes decide to challenge us again.", sourceObjectiveStatus = "unverified-source-field" }
quests[13332] = { id = 13332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raise the Barricades", description = "When our forces begin to move beyond Aldur'thar, they will be vulnerable to attack from the Ironwall Rampart and the broad glacier below.\n\nWe have neither the time nor the materials to build fortifications, but we can put up some barricades to shield our men from fire and break up Scourge charges.\n\nTake this barricade kit to the Valley of Fallen Heroes, on the west side of Aldur'thar. Locate the markers I've placed there and use this kit to construct your barricades there.", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to construct 8 Barricades using your Barricade Construction Kit.", completion = "<Thassarian nods.>\n\nGood. It's not much protection, but it's better than nothing. That gate is still the perfect choke point if the Scourge commanders know what they're doing. We must gain control of as much of the surrounding area as possible.", sourceObjectiveStatus = "unverified-source-field" }
quests[13333] = { id = 13333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Capture More Dispatches", description = "Despite our efforts, the Horde continues to send scouts to the area of the Icecrown Glacier, to the west of the Ironwall Rampart and Aldur'thar.\n\nWe can't afford to let the Horde gain the upper hand with this scouting operation. Take the dart gun with you again and show the Orgrim's Hammer scouts no mercy! Bring the captured dispatches to me.\n\nThe Horde's wasted efforts will be our gain.", sourceObjective = "Capture 6 Orgrim's Hammer Dispatches from Orgrim's Hammer Scouts and bring them to High Captain Justin Bartlett aboard the Skybreaker.", progress = "Have you intercepted those dispatches?", completion = "<The high captain accepts the dispatches.>\n\nThis is just what we need. Not even the Horde is so stupid as to charge in blindly against the Scourge. With their reports in hand, we'll be well prepared.", sourceObjectiveStatus = "unverified-source-field" }
quests[13334] = { id = 13334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodspattered Banners", description = "In the Valley of Fallen Heroes and Icecrown Glacier, to the west of Aldur'thar, the Scourge seeks to use the fallen against us. Scourge lieutenants have woken the valley's dead and imbued them with fearsome strength and fervor. The banners carried by the Scourge leaders in the glacier area are the source of these powers. Kill the banner-bearers, and you will weaken the converted heroes they lead.\n\nIt falls to you to rid us of this obstacle, and test the resistance before the main body can advance.", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to kill 5 Scourge Banner-Bearers, 5 Scourge Converters, and 20 Converted Heroes.", progress = "Have you killed the banner-bearers and stopped their attempt to use the fallen against us?", completion = "You have removed the Scourge banner-bearers and their minions? Good. Our preparations must continue.", sourceObjectiveStatus = "unverified-source-field" }
quests[13335] = { id = 13335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Before the Gate of Horror", description = "The Conflagration, the ground before Corp'rethar, south of the Ironwall Rampart, is where the Lich King's elite soldiers have formed up to defend the citadel.\n\nLed by a contingent of death knights, a legion of skeletal reavers bars the way. I fear that even when these reavers fall, the Scourge will simply reconstitute them and send them back at us.\n\nI've come up with a plan to stop this, but I have no way of knowing if it will work. Take this solution and use it to dissolve the remains of the reavers.", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to use the Volatile Acid to dissolve the corpses of 6 Skeletal Reavers.", completion = "<Thassarian listens as you describe your successful tests.>\n\nSo the acid worked? Good. We'll need it when the army goes up against the reavers in force.", sourceObjectiveStatus = "unverified-source-field" }
quests[13336] = { id = 13336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of the Chosen", description = "Those vrykul that have gained the favor of the Lich King call themselves the Ymirjar. They inhabit a city in the center of Icecrown. We have a lot of preparations to make before we assault Icecrown Citadel, and the one that stands before us now is routing these so-called \"Chosen\" of the Lich King.\n\nGo to their city, Ymirheim, and slaughter them in their home. Let there be no questions as to who the stronger combatants are here.", sourceObjective = "Knight-Captain Drosche on the Skybreaker has sent you to kill 20 vrykul in Ymirheim.", completion = "The traitor king will fall. Of that I have no doubt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13337] = { id = 13337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ironwall Rampart", description = "The Ironwall Rampart overlooks the Valley of Fallen Heroes, west of Aldur'thar. The rampart dominates the fields below on all sides. We will not be able to advance if the rampart cannot be taken, but it is held by Grimkor the Wicked and his Cult of the Damned disciples.\n\nIf you can weaken Grimkor, our forces will know what to expect as we advance. Take this rune of distortion. Unleashing its power near Grimkor's orb at the end of the rampart should be enough to get the necromancer's attention.", sourceObjective = "Defeat Grimkor the Wicked and return to Thassarian aboard the Skybreaker.", progress = "Have you completed your mission?", completion = "So Grimkor has fallen by your hand? Excellent work. With him out of the way, our chances of taking and holding the rampart during the assault are greatly improved.", sourceObjectiveStatus = "unverified-source-field" }
quests[13338] = { id = 13338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Guardians of Corp'rethar", description = "Corp'rethar, called the Horror Gate. It is the last barrier between us and the Icecrown Citadel. It waits to the south of the Ironwall Rampart, beyond the glacier and the Conflagration. By the time our troops reach it, they will be exhausted and worse.\n\nWe must weaken its defenses, or our army's strength will break upon its walls.\n\nIts battlements are manned by some of the Lich King's fiercest and most zealous servants. Do all you can to destroy these guardians and hope it is enough.", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to kill 5 Harbingers of Horror and 5 Corp'rethar Guardians.", completion = "I hope your success at Corp'rethar will prove an omen of the battle ahead. The Lich King cannot sit idly by as we march to the very gates of his stronghold.", sourceObjectiveStatus = "unverified-source-field" }
quests[13339] = { id = 13339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shatter the Shards", description = "Atop the battlements of Corp'rethar, the Lich King's minions have erected three crystals, the shards of horror, despair, and suffering. Should our men reach the walls of Corp'rethar, he will unleash these weapons on our army.\n\nIn full effect, the crystals will afflict the minds of our men with paralyzing pain and fear. Then, the Scourge will be able to slaughter them at will.\n\nFind these shards, destroy them, and bring me their broken remains. We cannot allow the Lich King to deploy these weapons!", sourceObjective = "Bring the Broken Shard of Horror, the Broken Shard of Despair, and the Broken Shard of Suffering to Thassarian, aboard the Skybreaker.", progress = "Have you shattered the Lich King's new weapons?", completion = "<Thassarian takes the crystal shards from you and speaks in a quiet voice.>\n\nI remember these...\n\nLesser men would easily crumble beneath their assault. You have done well in removing their threat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13340] = { id = 13340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Joining the Assault", description = "We need more men to join the main assault on Ymirheim.\n\nAny warrior with half a brain can tell you that vrykul are fierce fighters and should not be taken lightly. That goes two-fold for the Ymirjar. They have shown us no restraint in proving why the Lich King deemed them worthy.\n\nGround Commander Xutjja is overseeing the assault. The city itself is located in the center of Icecrown - Xutjja's troops are positioned near the edge of the glacier, north of the city.", sourceObjective = "Report to Ground Commander Xutjja at the edge of the glacier north of Ymirheim.", completion = "More meat for the grinder. Welcome to hell, soldier.\n\nMy men are leading the assault on the gate from this position, and we're dropping some infiltrators in the city via air - we need more people on both fronts. I have a feeling that this attack will be going on for some time.", sourceObjectiveStatus = "unverified-source-field" }
quests[13341] = { id = 13341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Joining the Assault", description = "We need more men to join the main assault on Ymirheim.\n\nAny warrior with half a brain can tell you that vrykul are fierce fighters and should not be taken lightly. That goes two-fold for the Ymirjar. They have shown no restraint in proving to us why the Lich King deemed them worthy.\n\nGround Commander Koup is overseeing the assault. The city itself is located in the center of Icecrown - Koup's troops are positioned near the edge of the glacier, east of the city.", sourceObjective = "Report to Ground Commander Koup at the edge of the glacier east of Ymirheim.", completion = "Welcome to hell, soldier.\n\nMy men are leading the assault on the gate from this position, and we're dropping some infiltrators in the city via air - we need more people on both fronts. I have a feeling that this attack will be going on for some time.", sourceObjectiveStatus = "unverified-source-field" }
quests[13342] = { id = 13342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not a Bug", description = "Alright, <friend/missy>, time to plant a bug.\n\nRelax, it's not a bug exactly, but it'll serve our purposes.\n\nIn the northern portion of Aldur'thar the cult's void summoners enslave demonic minions. Use this rod to siphon the dark matter from the corpses of these enslaved minions, and then use their summoning crystal to bring our little spy into being.\n\nUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur'thar.", completion = "You have done well, {class}.\n\nThe messenger has already turned up some valuable information.", sourceObjectiveStatus = "unverified-source-field" }
quests[13343] = { id = 13343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystery of the Infinite, Redux", description = "There you are! Or, were we just talking?\n\n<Chromie muses over the temporal possibilities.>\n\nAnyway, the Infinites are after you! Well, not you per-se. Rather, they're after the past version of you that defended the Hourglass of Eternity. You remember, right?\n\nThat was you back then, except it's you now too. Wait, that's not important. What is important is that you head back to the Bronze Dragonshrine and defend yourself and the hourglass from their attacks before you get erased from history!", sourceObjective = "Chromie, at the top of Wyrmrest Temple, has asked you to travel once more to the Bronze Dragonshrine.\n\nOnce inside, place the Hourglass of Eternity on the ground and help your Past Self to protect it from the forces of the Infinite Dragonflight.", progress = "<Chromie looks at you strangely.>\n\nDo I know you? I sense an aura about you as if your very existence is in flux. Either that or you're stuck in a time loop.\n\nWhatever the reason, you'd better fix it fast or you won't exist for very long at all!", completion = "Oh my goodness, you made it! I was uncertain.\n\nYou flickered in and out of the time stream there for a moment during the fight! I thought for sure that we'd lost you!\n\nBut here you are safe and sound, with your past self rescued, on the other side of the time loop you were in.\n\nYou're quite the temporal hero, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13344] = { id = 13344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not a Bug", description = "The cultists have discovered the last messenger you summoned, {race}.\n\nWhile it was quite informative, it's important that we continue to monitor their every move.\n\nUse this rod to siphon the dark matter from the corpses of enslaved minions at Aldur'thar. Then use their summoning crystal to bring another dark messenger into being.\n\nUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur'thar.", completion = "Well done, friend.\n\nThe messenger is up and reporting in as we speak.", sourceObjectiveStatus = "unverified-source-field" }
quests[13345] = { id = 13345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Need More Info", description = "The Cult of the Damned are notorious for concocting grandiose plans that in the end, rarely succeed. But something feels different this time....\n\nPerhaps it's the proximity to the Lich King that has their fervor heightened. Whatever it is, they appear to be more confident than ever. We must know what feeds this bravado and then find a way to strip them of it!\n\nI believe the key lies with their researchers. Find out what they're up to and report back to me with the details.", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to collect the 3 pages of Cultists' Research from the Cult Researchers at Aldur'thar and use them to create the Cult of the Damned Thesis.", progress = "Have you determined what their researchers are up to, {race}?", completion = "This is alarming, indeed....", sourceObjectiveStatus = "unverified-source-field" }
quests[13346] = { id = 13346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Rest For The Wicked", description = "These fools have actually stumbled upon something that could pose a serious threat to our plans!\n\nThe leader of this particular sect, Alumeth, has ritualistically sacrificed himself and now his underlings are channeling power to his soul.\n\nIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.\n\nCombine his heart, skull, scepter and robes from around their chamber and use his remains on the crystal there.\n\nHurry, {race}! Destroy him before he becomes any more powerful!", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to defeat Alumeth the Ascended at Aldur'thar.", progress = "Well, friend? Were you successful against Alumeth?", completion = "Alumeth has suffered a sound defeat, but I sense that his spirit still lingers...", sourceObjectiveStatus = "unverified-source-field" }
quests[13347] = { id = 13347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reborn From The Ashes", description = "Our fate is emblazoned upon our souls at birth. Bolvar's fall, while tragic, was unavoidable.\n\nAll that you can do now is honor your hero, {name}. Collect Bolvar's shield from the field of battle and return it to your king. When you present the shield to Varian, tell him this: \"All is not lost. From the ashes of the fallen will rise a force that will unite nations and purge the evil from this world.\"\n\nHe mustn't lose faith. Go now, {name}. Your people need a hero. They need you.", sourceObjective = "Gather Fordragon's Shield from the field of battle at Angrathar the Wrath Gate and return it to King Varian Wrynn at Stormwind Keep in Stormwind City.", progress = "<King Wrynn brushes away a tear.>\n\n<King Wrynn nods.>\n\nThis is my fault.", completion = "The Dragon Queen is right, {name}. All is not lost. I will be the force that rises from the ashes and I will purge the evil of the Horde from this world. The deaths of our brothers and sisters will not have been in vain.", sourceObjectiveStatus = "unverified-source-field" }
quests[13348] = { id = 13348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Futility", description = "Do you see now?  Sending your men against the prince's armies just swells their numbers.\n\nI don't expect you to understand... you'll probably just end up like the others.  You'd best return to whoever sent you.  They might be worried.", sourceObjective = "Return to Koltira Deathweaver aboard Orgrim's Hammer.", completion = "There you are.  Nice work down in the valley.  The carnage was visible all the way up here.\n\nAre you okay?  You look like you've seen a ghost.", sourceObjectiveStatus = "unverified-source-field" }
quests[13349] = { id = 13349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cradle of the Frostbrood", description = "We need to keep our momentum going.  Let's not give the Scourge forces any respite.\n\nSindragosa's Fall lies east just beyond the Valley of Lost Hope.  The Cult of the Damned operate there, under close supervision of the Lich King's undead vrykul lackeys.\n\nIt is a place of great power, possibly a blue dragonflight graveyard.  The feared frostbrood are raised there from the bones of blue dragons.\n\nAn attack there would have great impact on the enemy's access to frost wyrms.  Are you up to it, {name}?", sourceObjective = "Koltira Deathweaver aboard Orgrim's Hammer wants you to slay 5 Wyrm Reanimators, 8 Cultist Corrupters and 3 Vrykul Necrolords at Sindragosa's Fall.", progress = "Hail, {name}.", completion = "You've done well, {name}.  You might want to rest for a while.  You look a little pale.", sourceObjectiveStatus = "unverified-source-field" }
quests[13350] = { id = 13350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Rest For The Wicked", description = "It's Alumeth... He's growing in power again. I can sense it. Again his underlings are channeling power to his soul.\n\nIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.\n\nReturn to his chamber in the north portion of Aldur'thar. Combine his heart, skull, scepter and robes, then use his remains on the crystal there.\n\nHurry, {race}! Destroy him before he becomes any more powerful!", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to defeat Alumeth the Ascended at Aldur'thar.", completion = "Alumeth has suffered a sound defeat, but I sense that his spirit still lingers...", sourceObjectiveStatus = "unverified-source-field" }
quests[13351] = { id = 13351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sneak Preview", description = "Progress is being made. We have a promising array of tactics that should gain us control of the death gate. There will doubtlessly be many casualties, but in the end,  we should be able to prevail - barring any interference from the Alliance.\n\nOur next focus will be Aldur'thar, the gate of desolation. Fly down and become familiar with it and with the enemies posted there.\n\nWhen you return, I will have your missions prepared.", sourceObjective = "Koltira, aboard Orgrim's Hammer, wants you to fly down to the gate of desolation, visiting the south, central, north, and northwest regions of the gate.", progress = "Have you scouted the gate of desolation, {class}?", completion = "Well and good, {class}.\n\nNow that you've seen firsthand what we're up against, it's time to get to work...", sourceObjectiveStatus = "unverified-source-field" }
quests[13352] = { id = 13352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drag and Drop", description = "The Cult of the Damned hold the gate of desolation, eh? No surprise there.\n\nTime to have a little fun. At the southern end of the gate, you mentioned there were new cultists being trained. They're almost certain to be holding a special item given to all initiates - an Orb of Illusion.\n\nThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.\n\nKill the fools until you find one, {class}, then use it on a subjugator.", sourceObjective = "Koltira, aboard Orgrim's Hammer, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur'thar and use them on 3 Dark Subjugators there.", completion = "An effective tool, given the circumstances, wouldn't you say?\n\nThat one never gets old....", sourceObjectiveStatus = "unverified-source-field" }
quests[13353] = { id = 13353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drag and Drop", description = "Looks like those initiates are increasing in number again. You know what to do...\n\nAt the southern portion of the gate, the new cultists are being trained. They're certain to be holding a special item given to all initiates - an Orb of Illusion.\n\nThese artifacts are used to disguise a cult member, allowing them to gain safe passage, infiltrate, or simply blend in with an enemy.\n\nSlay the fools until you find some, then use them on the subjugators there.", sourceObjective = "Koltira, aboard Orgrim's Hammer, wants you to collect Orbs of Illusion from Bitter Initiates at Aldur'thar and use them on 3 Dark Subjugators there.", progress = "Yes, {race}?", completion = "An effective tool, given the circumstances, wouldn't you say?\n\nThat one never gets old....", sourceObjectiveStatus = "unverified-source-field" }
quests[13354] = { id = 13354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chain of Command", description = "Based on your report, and my knowledge of the Cult, they have an overseer managing the operation of each encampment on the gate.\n\nWhile taking their leaders down will only be a temporary setback, it will at least slow them down and keep them off-balance. And that, {race}, is a worthy enough goal for now.\n\nSeek out these overseers and return to me when they have been dispatched.", sourceObjective = "Koltira aboard Orgrim's Hammer wants you to go to Aldur'thar and defeat Overseer Faedris, Overseer Savryn, Overseer Veraj, and Overseer Jhaeqon.", completion = "Well done, {race}. But don't break your arm patting yourself on the back. They'll have those overseers replaced in no time...", sourceObjectiveStatus = "unverified-source-field" }
quests[13355] = { id = 13355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cannot Reproduce", description = "I smell their cauldrons from here, but that's not plague they're cooking.\n\nPledges to the cult are forced to drink a concoction that steals their will and enslaves them forever to the Lich King.\n\nSome say the potion contains the twisted soul of a being who was tormented before being mercilessly slaughtered, but I've never been able to reproduce it...\n\nFill this flask with a sample from each of the three cauldrons in the northwest region of the gate and bring it to Chief Engineer Copperclaw.", sourceObjective = "Koltira aboard Orgrim's Hammer wants you to use the Partitioned Flask at each of the 3 Cultists' Cauldrons at Aldur'thar, then bring it to Chief Engineer Copperclaw.", progress = "Whatdya got there, {class}?", completion = "<Copperclaw pours the contents of the flask into his particle analyzer.>\n\nAhh... I know just the thing!", sourceObjectiveStatus = "unverified-source-field" }
quests[13356] = { id = 13356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retest Now", description = "This should do the trick!\n\nThose twisted hooligans are looking for souls to put in their crazy-juice? Then I say we help 'em out a bit!\n\nTake a swig of this - don't worry, I've diluted it plenty... Its only effect will be to detect any cultist's essence once you've defeated them.\n\nWhen you've collected a bunch of essences, throw the writhing mass of twisted souls into any of their cauldrons.\n\nLet's see how they like a taste of their own medicine!", sourceObjective = "Chief Engineer Copperclaw aboard Orgrim's Hammer wants you to throw a Writhing Mass into a cauldron at Aldur'thar.", completion = "Wahoo!\n\nThat'll teach 'em!", sourceObjectiveStatus = "unverified-source-field" }
quests[13357] = { id = 13357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retest Now", description = "Those twisted cultists are looking for souls to put in their crazy-juice? Then let's help 'em out a bit!\n\nTake a swig of this - don't worry, I've diluted it plenty... I'm almost positive that its only effect will be to detect any cultist's essence.\n\nOnce you've collected a bunch of 'em, throw the writhing mass of twisted souls in one of their cauldrons.\n\nLet's see how they like a taste of their own medicine!", sourceObjective = "Chief Engineer Copperclaw aboard Orgrim's Hammer wants you to throw a Writhing Mass into a cauldron at Aldur'thar.", completion = "Wahoo!\n\nThat'll teach 'em!", sourceObjectiveStatus = "unverified-source-field" }
quests[13358] = { id = 13358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not a Bug", description = "Alright, <friend/missy>, time to plant a bug.\n\nRelax, it's not a bug exactly, but it'll serve our purposes.\n\nIn the northern portion of Aldur'thar, the cult's void summoners enslave demonic minions. Use this rod to siphon the dark matter from the corpses of these enslaved minions, and then use the cultists' summoning crystal to bring our little spy into being.\n\nUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.", sourceObjective = "Koltira, aboard Orgrim's Hammer, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur'thar.", completion = "You have done well, {class}.\n\nThe messenger has already turned up some valuable information.", sourceObjectiveStatus = "unverified-source-field" }
quests[13359] = { id = 13359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Dragons Fell", description = "A whole brood of blue dragons fell here.  And now, one by one, they're being raised by his servants.\n\nHe raised the biggest of them all himself.  Bring me some bone dust from the whelps and I'll show you exactly how he did it.", sourceObjective = "Matthias Lehner at Sindragosa's Fall wants you to obtain 6 Whelp Bone Dusts.", progress = "Did you get the dust, {name}?", completion = "Even the mighty wyrms had to heed his call.  How is a simple mortal like you going to resist him?", sourceObjectiveStatus = "unverified-source-field" }
quests[13360] = { id = 13360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time for Answers", description = "You have a lot of questions, {name}.  You're the only one who can see me because you touched something that once belonged to him... don't you remember?\n\nYou don't know what it is?  Well I can't just tell you... that would make him really mad.  He's not just a prince anymore... he's the king!\n\nMeet me at the Court of Bones, north of Icecrown Citadel and you can see for yourself.", sourceObjective = "Speak to Matthias Lehner at the Court of Bones.", completion = "There you are.  I started to wonder whether you'd show up.", sourceObjectiveStatus = "unverified-source-field" }
quests[13361] = { id = 13361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter and the Prince", description = "Before the prince became a king, he fought many battles... but only one where he came close to dying.\n\nIt was fought right here.  After you let me show you what happened, you'll understand everything.\n\nFind a bloodstained stone and pick it up from the floor.  You'll see what happened.", sourceObjective = "Matthias Lehner in the Court of Bones wants you to look for a Bloodstained Stone and complete the Prince's Destiny.", progress = "Did you see, {name}?  Did you?", completion = "After that fight, the prince realized what was holding him back was that he was still human... he could still feel... he could still bleed.  He still had a heart.\n\nThe first thing he did when he became king was to rid of himself of it.  He threw it down the pit where we first met.  And you, {name}, were the first person to touch it since.", sourceObjectiveStatus = "unverified-source-field" }
quests[13362] = { id = 13362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knowledge is a Terrible Burden", description = "Now you know what you're up against, {name}.  An opponent who no longer knows pain... remorse... or humanity.  An opponent who will do anything to get what he wants.\n\nThe heart was his weakness and now he knows you've found it.\n\nIf you're going to go back for it, you'd best bring help.  He will not leave it unguarded again.", sourceObjective = "Report back to Koltira aboard Orgrim's Hammer.", completion = "Little kid's ghost... Arthas's heart... you'd better slow down... you're making my head spin.", sourceObjectiveStatus = "unverified-source-field" }
quests[13363] = { id = 13363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Argent Aid", description = "There were rumors about the events you speak of among the death knights.  I always expected the story to be more... symbolic.\n\nWe must warn others, but we must be discreet.  As soon as the Lich King knows we're making our move, he'll move the location of the heart -- we'll never get a chance like this again.\n\nThe Horde and the Alliance have been infiltrated by the Cult of the Damned before.  The Ebon Blade operates too close to the Scourge.\n\nWe have to speak to Tirion Fordring and his Argent Crusade.", sourceObjective = "Speak to Highlord Tirion Fordring at the Crusader's Pinnacle.", completion = "Heavy words, {name}.  If it were somebody else saying them, I'd be likely to judge them insane.", sourceObjectiveStatus = "unverified-source-field" }
quests[13364] = { id = 13364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tirion's Gambit", description = "Just this morning, my scouts informed me of a Cult of the Damned procession leaving from Icecrown Citadel to the Cathedral of Darkness, bearing an artifact.\n\nAnd now I learn that it might be Arthas's own heart... a thing containing the last bit of his remaining humanity.\n\nThis is a sign of the Light.  As long as such an artifact exists, there is a chance that Arthas Menethil can become a man again!\n\nMeet me at the cathedral's entrance.  Be sure to bring a cultist's hood -- we're going incognito.", sourceObjective = "Tirion Fordring, at the Crusader's Pinnacle, wants you to obtain and wear a Cultist Acolyte's Hood and meet him at the entrance of the Cathedral of Darkness, northwest of Icecrown Citadel.", progress = "Light be with you, {name}.", completion = "I do not view what we just went through as a failure, {name}... quite the opposite.\n\nBy allowing me to peer into his heart, you allowed me to confirm what I needed to know.  There is no Arthas Menethil anymore -- there is only the Lich King.", sourceObjectiveStatus = "unverified-source-field" }
quests[13365] = { id = 13365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not a Bug", description = "The cultists have discovered the last messenger you summoned, {race}.\n\nWhile it was quite informative, it's important that we continue to monitor the cult's every move.\n\nUse this rod to siphon the dark matter from the corpses of enslaved minions at Aldur'thar. Then use their summoning crystal to bring another dark messenger into being.\n\nUntil it is discovered, the messenger will serve as our eyes and ears, discreetly observing the actions of our enemy.", sourceObjective = "Koltira, aboard Orgrim's Hammer, wants you to collect 5 Dark Matters and summon a Dark Messenger at Aldur'thar.", progress = "Yes, {class}?", completion = "Well done, friend.\n\nThe messenger is up and reporting in as we speak.", sourceObjectiveStatus = "unverified-source-field" }
quests[13366] = { id = 13366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Need More Info", description = "The Cult of the Damned are notorious for concocting grandiose plans that in the end, rarely succeed. But something feels different this time....\n\nPerhaps it's the proximity to the Lich King that has their fervor heightened. Whatever it is, they appear to be more confident than ever. We must know what feeds this bravado and then find a way to strip them of it!\n\nI believe the key lies with their researchers. Find out what they're up to and report back to me with the details.", sourceObjective = "Koltira, aboard Orgrim's Hammer, wants you to collect the 3 pages of Cultists' Research from the Cult Researchers at Aldur'thar and use them to create the Cult of the Damned Thesis.", progress = "Have you discovered what their researchers are up to, {class}?", completion = "This is alarming, indeed....", sourceObjectiveStatus = "unverified-source-field" }
quests[13367] = { id = 13367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Rest For The Wicked", description = "These fools have actually stumbled upon something that could pose a serious threat to our plans!\n\nThe leader of this particular sect, Alumeth, has ritualistically sacrificed himself and now his underlings are channeling power to his soul.\n\nIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.\n\nCombine his heart, skull, scepter and robes from around their chamber and use his remains on the crystal there.\n\nHurry, {race}! Destroy him before he becomes any more powerful!", sourceObjective = "Koltira, aboard Orgrim's Hammer, wants you to slay Alumeth the Ascended at Aldur'thar.", completion = "Alumeth has suffered a sound defeat, but I sense that his spirit still lingers...", sourceObjectiveStatus = "unverified-source-field" }
quests[13368] = { id = 13368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Rest For The Wicked", description = "It's Alumeth... He's growing in power again. I can sense it. Again his underlings are channeling power to his soul.\n\nIf he's allowed to rest, their efforts will soon transform him into a mighty adversary.\n\nReturn to his chamber in the north portion of Aldur'thar. Combine his heart, skull, scepter and robes, then use his remains on the crystal there.\n\nHurry, {race}! Destroy him while there's still time!", sourceObjective = "Koltira, aboard Orgrim's Hammer, wants you to slay Alumeth the Ascended at Aldur'thar.", progress = "Well, friend? Were you successful against Alumeth?", completion = "Alumeth has suffered a sound defeat, but I sense that his spirit still lingers...", sourceObjectiveStatus = "unverified-source-field" }
quests[13369] = { id = 13369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate, Up Against Your Will", description = "At the behest of Lady Proudmoore, I will allow a diplomatic mission to Orgrimmar to question the Horde's Warchief, Thrall. You will assist her in this journey and keep her safe from harm. Return to me with news from Orgrimmar.\n\nSpeak to Jaina when you are ready to leave.", sourceObjective = "Assist Lady Jaina Proudmoore in Orgrimmar. Speak to the Warchief of the Horde, Thrall, at Orgrimmar on the continent of Kalimdor.", completion = "The Horde does not want war, {race}. Listen well...", sourceObjectiveStatus = "unverified-source-field" }
quests[13370] = { id = 13370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Royal Coup", description = "Your champion, Bolvar, died in defense of our world. The Horde is saddened by the loss of such a great hero, but the Horde was not responsible for the cowardly attacks made by Putress at the Wrath Gate. We have also lost mighty heroes because of this betrayal.\n\nTell your king that we will do everything in our power to bring the perpetrators of this cowardly act to justice. We will do all that we can to avoid conflict with the Alliance, but we will not hesitate to defend ourselves if provoked.", sourceObjective = "Use the portal in Grommash Hold to return to Stormwind Keep and deliver Thrall's message to King Varian Wrynn.", completion = "They have lost the Undercity? Then the time to strike is now. We will deal with Putress ourselves and retake the Ruins of Lordaeron for the Alliance!", sourceObjectiveStatus = "unverified-source-field" }
quests[13371] = { id = 13371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Killing Time", description = "I sent Broll and Valeera to the Undercity before you left for Orgrimmar. In fact, they're now stationed outside the sewer entrance to the ruins, awaiting orders.\n\nLady Proudmoore will open a portal to our forces outside the Undercity. Go there and report to Broll. Jaina and I will be close behind.", sourceObjective = "Use the Portal to the Undercity inside Stormwind Keep to teleport to the Undercity. Report to Broll Bearmantle when you arrive at your destination.", completion = "Who are you supposed to be? Varian said he'd send heroes.", sourceObjectiveStatus = "unverified-source-field" }
quests[13372] = { id = 13372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Key to the Focusing Iris", description = "A potent thrumming of magical nature can be heard and felt emanating from the eye-shaped jewel dropped from Sapphiron's clutches. To mortal ears it is nearly painful to be in the presence of the stone.\n\nSurely such a powerful item of import can only be taken to the queen of the dragons, Alexstrasza the Life-Binder. Seek her counsel atop Wyrmrest Temple in the Dragonblight.", sourceObjective = "Deliver the Key to the Focusing Iris to Alexstrasza the Life-Binder atop Wyrmrest Temple in the Dragonblight.", progress = "{name}, you have come into contact with a key to the focusing iris! Do you have it upon your person?\n\n\n\nHow did you ever come into its possession? Oh, Sapphiron still had his?", completion = "These keys are held by the most ancient members of the blue dragonflight. Only they are entrusted with them by their master, Malygos.\n\nThis is the break that we've been waiting for to strike at the Aspect of Magic!\n\n<The queen of dragons studies you for a brief moment.>\n\nYou are not able to use the key as-is to access the Focusing Iris, but I can imbue you with a portion of my power; enough to enable you to use it to open the iris a fraction.\n\nIt will be enough to draw Malygos's ire!", sourceObjectiveStatus = "unverified-source-field" }
quests[13373] = { id = 13373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fringe Science Benefits", description = "I installed our infra-green technology into commandeered bombers; it'll protect you on your first mission into enemy territory!  Speak with Rizzy Ratchwiggle to get a bomber, then fly into The Bombardment!\n\nYou'll have bombs and rockets and shields.  Keep the shields charged and use bombs on the ground Scourge at The Bombardment.  Come back after you hit your targets, and more work will await you.", sourceObjective = "Fringe Engineer Tezzla wants you to kill 40 Bombardment Infantry, 8 Bombardment Captains and 15 Gargoyle Ambushers.", progress = "You haven't reached your target quota, {name}.  Are the bombers too hard to handle?", completion = "Hah, you got them!  How did you like the bomber?  I hope you got the hang of it, because I have more missions for you...", sourceObjectiveStatus = "unverified-source-field" }
quests[13374] = { id = 13374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amped for Revolt!", description = "{name}, only our best pilots are given a mission like this, one deep, deep into enemy territory with only the power of infra-green technology to protect you!\n\nRequest another bomber from Rizzle, and this time fly it through the Valley of Lost Hope.  You have both air and ground targets on this mission, so keep your eyes open and your shields at full!\n\nGood luck!", sourceObjective = "Fringe Engineer Tezzla wants you to kill Bombardment Infantry, Gargoyle Ambushers, Frostbrood Sentries and Scourge War Machines.", sourceObjectiveStatus = "unverified-source-field" }
quests[13375] = { id = 13375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heroic Key to the Focusing Iris", description = "A potent thrumming of magical nature can be heard and felt emanating from the eye-shaped jewel dropped from Sapphiron's clutches. To mortal ears it is nearly painful to be in the presence of the stone.\n\nSurely such a powerful item of import can only be taken to the queen of the dragons, Alexstrasza the Life-Binder. Seek her counsel atop Wyrmrest Temple in the Dragonblight.", sourceObjective = "Deliver the Heroic Key to the Focusing Iris to Alexstrasza the Life-Binder atop Wyrmrest Temple in the Dragonblight.", progress = "{name}, you have come into contact with a key to the iris! Do you have it upon your person?\n\n\n\nHow did you ever come into its possession? Oh, Sapphiron still had his?", completion = "These keys are held by the most ancient members of the blue dragonflight. Only they are entrusted with them by their master, Malygos.\n\nThis is the break that we've been waiting for to strike at the Aspect of Magic!\n\n<The queen of dragons studies you for a brief moment.>\n\nYou are not able to use the key as-is to access the Focusing Iris, but I can imbue you with a portion of my power; enough to enable you to use it to open the iris a fraction.\n\nIt will be enough to draw Malygos's ire!", sourceObjectiveStatus = "unverified-source-field" }
quests[13376] = { id = 13376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Total Ohmage: The Valley of Lost Hope!", description = "{name}, the struggle continues.  Lucky for us, we're stocked up on bombs and rockets!  Time for another bombing mission  --  this one's a long one, through the Bombardment and into the Valley of Lost Hope.  Head back out with an infra-green bomber and blow those Scourge into little scourge-lets!", sourceObjective = "Fringe Engineer Tezzla wants you to kill 50 Bombardment Infantry, 20 Gargoyle Ambushers, 12 Frostbrood Sentries and 12 Scourge War Machines.", progress = "What are you waiting for?  We have the hardware and the ordinance... we just need brave gunners like you to apply them.", completion = "Great work, {name}.  While you were out, I heard other gunners talking about you... I think you have a real future in air offense!", sourceObjectiveStatus = "unverified-source-field" }
quests[13377] = { id = 13377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle For The Undercity", description = "Deep inside the bowels of the Undercity hides the assassin responsible for the deaths of Bolvar and our brave soldiers at the Wrath Gate.\n\nVarian has brought the full might of the Alliance with him to assist in the take down. Join him and Lady Proudmoore in the manhunt and earn your place among the greatest champions of the Alliance!\n\nSpeak to King Varian Wrynn when you are ready.", sourceObjective = "Assist King Varian Wrynn and Lady Jaina Proudmoore in bringing Grand Apothecary Putress to justice! Report to King Varian Wrynn should you succeed.", completion = "For too long have the Horde been left unchecked. We allowed their territories to prosper and in return for our generosity they plotted and planned our demise.\n\nPeace? Useless... It's gotten us nowhere. We have lost some of our greatest heroes to \"peace.\" Let us see what battle brings...\n\nReturn to Northrend, {name}. Conquer it for your king - FOR THE ALLIANCE!", sourceObjectiveStatus = "unverified-source-field" }
quests[13378] = { id = 13378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chief Engineer Copperclaw", description = "Speak with Chief Engineer Copperclaw." }
quests[13379] = { id = 13379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Green Technology", description = "Tezzla is the one you want to meet, yes she is... she mastered a new wavelength, infra-green, and used it to hide herself near the Scourge!  Near enough to bomb them!\n\nI'll give you infra-green vision so you can find her hiding above Aldur'thar, the Desolation Gate.  Go, go... I know she has work for brave heroes eager to blow up!  I mean... eager to blow up the Scourge!\n\nAnd {name}, the Alliance has stolen our technology and has their own hidden airport nearby.  Avoid the dome with the Alliance banners!", sourceObjective = "Speak with Fringe Engineer Tezzla.", completion = "Yes, yes!  You found me!  And just in time!", sourceObjectiveStatus = "unverified-source-field" }
quests[13380] = { id = 13380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leading the Charge", description = "Infra-green technology allows us to stay hidden here, right over the Scourge's nose!  What's more, we installed infra-green in specially constructed bombers... but not to hide them, no!  We use infra-green tech to shield them!\n\nSpeak with Karen No and request a bomber.  Fly it over the Bombardment... use its shields and turret to protect yourself, and use the bomb launcher to hit Scourge targets.  Practice well, then return to me and I'll have an even more vital mission for you!", sourceObjective = "Kibli Killohertz wants you to kill 40 Bombardment Infantry, 8 Bombardment Captains and 15 Gargoyle Ambushers.", progress = "{name}, the bombers are difficult to use, but you must master them if we're to win our struggles against the Scourge.", completion = "I could hear your explosions from here, {name}.  How did the shields work?  Did they keep your bomber intact?\n\nI hope they did, because now I have more missions for you....", sourceObjectiveStatus = "unverified-source-field" }
quests[13381] = { id = 13381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watts My Target", description = "Put on your lucky socks, {name}, and say your favorite prayers.  This next mission will test your wit and fortitude like a visit from the in-laws!\n\nRequest another bomber from Karen No.  Take it beyond The Bombardment and over the Valley of Lost Hope.  You have more targets this time, both on the land an in the air.  Keep your shields charged and your ammo loaded, {name}!  I'll see you when it's over.", sourceObjective = "Kibli Killohertz wants you to kill Bombardment Infantry, Gargoyle Ambushers, Frostbrood Sentries and Scourge War Machines.", sourceObjectiveStatus = "unverified-source-field" }
quests[13382] = { id = 13382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putting the Hertz: The Valley of Lost Hope", description = "The fight goes on!  Your new orders arrived for a long-range bombing mission through the Bombardment and into the Valley of Lost Hope -- when you're ready, ask Karen for a bomber and pour those bombs and rockets onto the Scourge!", sourceObjective = "Kibli Killohertz wants you to kill 50 Bombardment Infantry, 20 Gargoyle Ambushers, 12 Frostbrood Sentries and 12 Scourge War Machines.", progress = "Keep at them, {name}.  The air battle won't win itself!", completion = "Welcome back, {name}.  How was the battle?  Exciting?  Take a rest for now.  But come back when you have fresh orders.\n\nFor the Alliance!", sourceObjectiveStatus = "unverified-source-field" }
quests[13383] = { id = 13383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Killohertz", description = "The goblins got lucky and found a new energy.  They call it infra-green, and I'll be a one-eyed ogre if those psychos didn't strike green gold.\n\nGo find Kibli Killohertz.  He's leading the reverse engineering efforts of infra-green, at a small, hidden Alliance airport above Aldur'thar, the Desolation Gate.  I'll give you infra-green vision to help you find it.  Go to the dome with our Alliance banners -- if you fly near the Horde airport then you'll be in a load of green trouble.", sourceObjective = "Chief Engineer Boltwrench wants you to find Kibli Killohertz at the hidden Alliance airport above Aldur'thar, the Desolation Gate.", completion = "Yes, yes, yes!  A thousand times, hello!", sourceObjectiveStatus = "unverified-source-field" }
quests[13384] = { id = 13384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Judgment at the Eye of Eternity", description = "Now that you have access to the focusing iris it's time to put that key to use.\n\nAs much as I would like to see Malygos brought back into the fold, that's just not going to happen at this point. With everything that's at stake, it is the judgment of the other Dragon Aspects that the Spell-Weaver needs to be put down.\n\n<Krasus says this last with a great deal of trepidation.>\n\n{name}, travel to the Eye of Eternity, confront Malygos and return with the Heart of Magic.", sourceObjective = "Krasus atop Wyrmrest Temple in the Dragonblight wants you to return with the Heart of Magic.\n\nThis quest is for the Normal mode, 10-person version of The Eye of Eternity.", progress = "Only Malygos carries the Heart of Magic. It is his most prized possession.", completion = "This is a very sad day, not only for dragonkind, but for all of the living creatures of Azeroth. We have lost one of our most thoughtful, intelligent and ancient friends. Magic is now without its guardian.\n\nLet us hope that this was a wise decision in the coming years, {name}. A storm is still brewing on the horizon and now we are without one of our most powerful defenders.", sourceObjectiveStatus = "unverified-source-field" }
quests[13385] = { id = 13385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroic Judgment at the Eye of Eternity", description = "Now that you have access to the focusing iris it's time to put that key to use.\n\nAs much as I would like to see Malygos brought back into the fold, that's just not going to happen at this point. With everything that's at stake, it is the judgment of the other Dragon Aspects that the Spell-Weaver needs to be put down.\n\n<Krasus says this last with a great deal of trepidation.>\n\n{name}, travel to the Eye of Eternity, confront Malygos and return with the Heart of Magic.", sourceObjective = "Krasus atop Wyrmrest Temple in the Dragonblight wants you to return with the Heart of Magic.\n\nThis quest can be completed in both 10-person and 25-person versions of The Eye of Eternity.", progress = "Only Malygos carries the Heart of Magic. It is his most prized possession.", completion = "This is a very sad day, not only for dragonkind, but for all of the living creatures of Azeroth. We have lost one of our most thoughtful, intelligent and ancient friends. Magic is now without its guardian.\n\nLet us hope that this was a wise decision in the coming years, {name}. A storm is still brewing on the horizon and now we are without one of our most powerful defenders.", sourceObjectiveStatus = "unverified-source-field" }
quests[13386] = { id = 13386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exploiting an Opening", description = "I've got an interesting assignment for you, {name}.  If you're up for a challenge, that is.\n\nWe've been tipped off about an opening below Icecrown Citadel.  Our engineers have studied the layout and have decided it's a structural weakness.\n\nWe've sent some men there along with some \"borrowed\" saronite bombs.  They're under Captain Kendall's command.\n\nWith a little help we could deal a huge blow to the forces of the Scourge.  What do you say, {name}?", sourceObjective = "Speak to Captain Kendall below Icecrown Citadel.", completion = "Hail, {name}.  Thassarian mentioned you'd be dropping by.  Any friend of Thassarian's is my friend.  Well, any living friend of Thassarian, that is...  He does keep odd company.", sourceObjectiveStatus = "unverified-source-field" }
quests[13387] = { id = 13387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Securing the Perimeter", description = "The saronite bombs are in place, {name}.  We're only going to get one shot at this, however.  Let's make it count.\n\nWe need temporary control of the area for a safe detonation.  Let's try to put a dent in the Scourge's numbers.", sourceObjective = "Captain Kendall at Icecrown Citadel wants you to slay 10 Hulking Horrors.", progress = "For the Alliance!", completion = "You're as good as Thassarian said.  Good job!", sourceObjectiveStatus = "unverified-source-field" }
quests[13388] = { id = 13388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Set it Off!", description = "Things are looking good.  Let's do this.\n\nThe stack of bombs is right near the pit.  I'll start to evacuate the men.", sourceObjective = "Captain Kendall, below Icecrown Citadel, wants you to go to the nearby Saronite Bomb Stack to light the fuse.", completion = "These bombs look pretty potent.  They should at least put a dent in the surrounding structure.", sourceObjectiveStatus = "unverified-source-field" }
quests[13389] = { id = 13389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Short Fuse", description = "As you light the fuse, you notice that it is consumed by fire far quicker than you would expect.\n\nThe bombs are about to go off and your best chance at surviving is to lean towards the pit and hope the fall doesn't kill you.", sourceObjective = "Look for clues wherever the fall takes you.", completion = "This pulsing object is covered in a thick layer of ice.  It shimmers strangely beneath the water.", sourceObjectiveStatus = "unverified-source-field" }
quests[13390] = { id = 13390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Voice in the Dark", description = "The object is not a crystal at all, but some form of organ, encased in ice.\n\nAs you touch it, your hand reels in horrible pain.  You feel as if your hand has been cut, yet there is no visible wound.\n\nAs you collect your thoughts, you hear a young boy's voice nearby.\n\n\"You really shouldn't have done that.\"", sourceObjective = "Investigate the nearby voice in Naz'anak, the Forgotten Depths.", completion = "I saw him get rid of it, you know?  He threw it all the way down here.\n\nSaid he wouldn't need it anymore.  Said it made him weak.", sourceObjectiveStatus = "unverified-source-field" }
quests[13391] = { id = 13391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time to Hide", description = "You shouldn't have touched it.  But now that you did, he's going to come looking for you.\n\nAnd he'll find you.  Unless you hide yourself from him.\n\nBring me blood from the faceless ones if you want to live!", sourceObjective = "Matthias Lehner wants you to obtain 3 Faceless One's Blood.", progress = "Did you get the blood?", completion = "What are you waiting for?  You have to rub it on you!\n\nQuick!  Or he'll see you!", sourceObjectiveStatus = "unverified-source-field" }
quests[13392] = { id = 13392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Surface", description = "You should leave now.  You'll find a portal behind me.  It'll take you to the surface.\n\nWe'll meet again.  He'll be looking for you.\n\nIt's only a matter of time until he finds you.", sourceObjective = "Return to Thassarian aboard the Skybreaker.", completion = "It's you, {name}!  We thought you were a goner.\n\nThat explosion of yours put quite a bit of hurt on the Scourge.  Nearly took Captain's Kendall's eyebrows off in the process...", sourceObjectiveStatus = "unverified-source-field" }
quests[13393] = { id = 13393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Repairs", description = "All right.  Let's not celebrate just yet.  We need to capitalize on the momentum we've gathered with our little bombing mission.\n\nWe've spotted a workable Horde demolisher-class catapult in the field below.  The geist seem to be taking it apart.\n\nIf you can put it back together, we'll be able to do some serious damage to the Scourge's armies in the Valley.\n\nSure, you'll be a little outnumbered, but I've a lot of faith in you!", sourceObjective = "Thassarian, aboard the Skybreaker, wants you to collect 5 Demolisher Parts from the Scavenging Geists and take them to the Wrecked Demolisher in the Valley of Lost Hope.", progress = "The demolisher has suffered much damage.", completion = "The demolisher has seen better days, but the structure hasn't suffered any permanent damage.  The parts you obtained should be enough to get it running again, at least temporarily.", sourceObjectiveStatus = "unverified-source-field" }
quests[13394] = { id = 13394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do Your Worst", description = "You're going to use this machine against the Scourge?  You're not going to win against them like that.\n\nYou can destroy hundreds... even thousands of them.  But you won't win.  Not out here.\n\nWhen you're done playing with your machine, meet me to the north.  There is an old army encampment.  What I will show you will teach you a little bit about who you're up against.", sourceObjective = "Use the Refurbished Demolisher to destroy 150 Decomposed Ghouls, 20 Frostskull Mages and 2 Bone Giants in the Valley of Lost Hope. Speak to Matthias Lehner at the First Legion Forward Camp when you've completed this task.", progress = "Are you done playing with your war machines?", completion = "You see?  You killed your fair share, but for every one you destroyed, another rose from the dirt to take its place.\n\nYou don't know what you're up against, {name}.  Let me show you.", sourceObjectiveStatus = "unverified-source-field" }
quests[13395] = { id = 13395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Army of the Damned", description = "You probably think you're quite strong -- fighting these undead and crushing their bones beneath your war machines.\n\nThat is nothing compared to the strength it took to create them.\n\nI saw the prince do it himself.  I can show you how it happened... if you'd like.", sourceObjective = "Matthias Lehner at the First Legion Forward Camp wants you to raise an army of 100 Ghoulish Minions.", completion = "The prince's true power wasn't his ability to make armies out of corpses... that was easy.\n\nBut killing his own men, with whom he'd shared many battles... the prince's true power was his ability to do what had to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[13396] = { id = 13396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Futility", description = "Do you see now?  Sending your men against the prince's armies just swells their numbers.\n\nI don't expect you to understand... you'll probably just end up like the others.  You'd best return to whoever sent you.  They might be worried.", sourceObjective = "Return to Thassarian aboard the Skybreaker.", completion = "Nice shooting, {name}.  The Scourge never had a chance.\n\nAre you feeling okay?  You look like you've seen a ghost.  Not that it would be an unusual thing around these parts, now that I think about it.", sourceObjectiveStatus = "unverified-source-field" }
quests[13397] = { id = 13397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sindragosa's Fall", description = "You're a real star, {name}.  See, when I give one of these other soldiers an assignment, the odds of them getting it done are about fifty-fifty.  The odds of them coming back... well, slightly worse.\n\nBut with you, it's always a guaranteed thing.  Like gnomish clockwork!\n\nAnyway, I have another one for you.  Sindragosa's Fall, east of the valley.  There is some serious cultist activity, including and not limited to, the raising of frost wyrms.  I need you to go kick their teeth in.\n\nI hate cultists.", sourceObjective = "Thassarian aboard the Skybreaker wants you to slay 5 Wyrm Reanimators, 8 Cultist Corrupters and 3 Vrykul Necrolords at Sindragosa's Fall.", completion = "Nice job, {name}.  You make the rest of us look bad!", sourceObjectiveStatus = "unverified-source-field" }
quests[13398] = { id = 13398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Dragons Fell", description = "A whole brood of blue dragons fell here.  And now, one by one, they're being raised by his servants.\n\nHe raised the biggest of them all himself.  Bring me some bone dust from the whelps and I'll show you exactly how he did it.", sourceObjective = "Matthias Lehner at Sindragosa's Fall wants you to obtain 6 Whelp Bone Dusts.", progress = "Did you get the dust, {name}?", completion = "Even the mighty wyrms had to heed his call.  How is a simple mortal like you going to resist him?", sourceObjectiveStatus = "unverified-source-field" }
quests[13399] = { id = 13399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time for Answers", description = "You have a lot of questions, {name}.  You're the only one who can see me because you touched something that once belonged to him... don't you remember?\n\nYou don't know what it is?  Well I can't just tell you... that would make him really mad.  He's not just a prince anymore... he's the king!\n\nMeet me at the Court of Bones, north of Icecrown Citadel and you can see for yourself.", sourceObjective = "Speak to Matthias Lehner at the Court of Bones.", completion = "There you are.  I started to wonder whether you'd show up.", sourceObjectiveStatus = "unverified-source-field" }
quests[13400] = { id = 13400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter and the Prince", description = "Before the prince became a king, he fought many battles... but only one where he came close to dying.\n\nIt was fought right here.  After you let me show you what happened, you'll understand everything.\n\nFind a bloodstained stone and pick it up from the floor.  You'll see what happened.", sourceObjective = "Matthias Lehner in the Court of Bones wants you to look for a Bloodstained Stone and complete the Prince's Destiny.", progress = "Did you see, {name}?  Did you?", completion = "After that fight, the prince realized what was holding him back was that he was still {race}... he could still feel... he could still bleed.  He still had a heart.\n\nThe first thing he did when he became king was to rid of himself of it.  He threw it down the pit where we first met.  And you, {name}, were the first person to touch it since.", sourceObjectiveStatus = "unverified-source-field" }
quests[13401] = { id = 13401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knowledge is a Terrible Burden", description = "Now you know what you're up against, {name}.  An opponent who no longer knows pain... remorse... or humanity.  An opponent who will do anything to get what he wants.\n\nThe heart was his weakness and now he knows you've found it.\n\nIf you're going to go back for it, you'd best bring help.  He will not leave it unguarded again.", sourceObjective = "Report back to Thassarian aboard the Skybreaker.", completion = "Slow down, {name}.  Why don't you start again... from the beginning?", sourceObjectiveStatus = "unverified-source-field" }
quests[13402] = { id = 13402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tirion's Help", description = "It's not the first time I've heard that story about Arthas and his heart... always thought it was some made-up tale to impress the rank and file.\n\nWe must act on this information immediately.  Unfortunately, we must do so in secret.\n\nArthas's agents are everywhere and if he finds out, our plan is dead in the water.\n\nWe need to take this to the Argent Crusade.  Every single paladin in that order was hand-picked by Tirion himself.  If there's anyone free of cultist infiltration, it's those guys.", sourceObjective = "Speak to Highlord Tirion Fordring at the Crusader's Pinnacle.", completion = "Heavy words, {name}.  If it were somebody else saying them, I'd be likely to judge them insane.", sourceObjectiveStatus = "unverified-source-field" }
quests[13403] = { id = 13403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tirion's Gambit", description = "Just this morning, my scouts informed me of a Cult of the Damned procession leaving from Icecrown Citadel to the Cathedral of Darkness, bearing an artifact.\n\nAnd now I learn that it might be Arthas's own heart... a thing containing the last bit of his remaining humanity.\n\nThis is a sign of the Light.  As long as such an artifact exists, there is a chance that Arthas Menethil can become a man again!\n\nMeet me at the cathedral's entrance.  Be sure to bring a cultist's hood -- we're going incognito.", sourceObjective = "Tirion Fordring, at the Crusader's Pinnacle, wants you to obtain and wear a Cultist Acolyte's Hood and meet him at the entrance of the Cathedral of Darkness, northwest of Icecrown Citadel.", progress = "Light be with you, {name}.", completion = "I do not view what we just went through as a failure, {name}... quite the opposite.\n\nBy allowing me to peer into his heart, you allowed me to confirm what I needed to know.  There is no Arthas Menethil anymore -- there is only the Lich King.", sourceObjectiveStatus = "unverified-source-field" }
quests[13404] = { id = 13404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Static Shock Troops: the Bombardment", description = "This is a short-ranged mission, over The Bombardment.  A good warm up.  Ready?", sourceObjective = "Kibli Killohertz wants you to kill 50 Bombardment Infantry, 10 Bombardment Captains and 20 Gargoyle Ambushers.", progress = "Keep at the, {name}.  The air battle won't win itself!", completion = "Welcome back, {name}.  A short mission, but invigorating, yes?  Take a rest for now.  But come back when you have fresh orders.", sourceObjectiveStatus = "unverified-source-field" }
quests[13405] = { id = 13405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Strand of the Ancients", description = "The fight in Northrend is not only against the armies of the Lich King, but also against those of the Horde.\n\nA powerful titan relic has been found in the Strand of the Ancients.  As you might know, we dwarves have been custodians of such artifacts for years and as such we're their rightful keepers.\n\nIn this case, the Horde has developed a keen interest in pilfering the relic from the titan ruins.  They're certain to use it as a weapon against us; we must do whatever we can to stop them.", sourceObjective = "Win a Strand of the Ancients battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", completion = "Excellent job, {name}!  With your help the Strand of the Ancients will be under complete Alliance control.", sourceObjectiveStatus = "unverified-source-field" }
quests[13406] = { id = 13406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riding the Wavelength: The Bombardment", description = "Ready to warm up with a short bombing mission?  You have your orders, and we have our bombers stocked and ready.", sourceObjective = "Fringe Engineer Tezzla wants you to kill 50 Bombardment Infantry, 10 Bombardment Captains and 20 Gargoyle Ambushers.", progress = "You haven't reached your target quota, {name}.  Get out there and blow stuff up!", completion = "Hah, you got them!  I could hear their Scourge parts clatter off the mountain walls.  Good work.  We'll have more for you soon...", sourceObjectiveStatus = "unverified-source-field" }
quests[13407] = { id = 13407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Strand of the Ancients", description = "Just because we march into Northrend to smash the Scourge, doesn't mean we get to take a break from crushing the Alliance.\n\nThose Explorers' League dwarves have found the location of a powerful titan relic and we'll be damned if we let the Alliance take control of it.\n\nGo, {name}, and destroy our enemies.  Make them see that no matter where we meet, they remain our sworn enemies.", sourceObjective = "Win a Strand of the Ancients battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", progress = "You're back!  Were you victorious, {name}?", completion = "You bring great honor to us, {name}!  The Alliance weaklings must be crushed under the heel of the mighty Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[13408] = { id = 13408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Fortifications", description = "The Hellfire Citadel wages constant battles with our forces.  We are holding our own so far, but we can't yet launch a real offensive against them.  To do that, we need forward staging areas.\n\nOur scouts identified three fortifications near Hellfire Citadel.  We want you to help secure these forts.  Capture each fort, and then report back to me.\n\nMay fortune shine upon you in the conflicts ahead, {name}, for you will no doubt clash with Horde forces eager to gain these same fortifications.", sourceObjective = "Capture the Overlook, the Stadium and Broken Hill, then return to Warrant Officer Tracy Proudwell in Honor Hold in Hellfire Peninsula.", progress = "{name}, return to me when you have aided in the capture of each of the forts!", completion = "Well done, {name}.  Your actions in the field are instrumental in our battle for Hellfire Peninsula.", sourceObjectiveStatus = "unverified-source-field" }
quests[13409] = { id = 13409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Fortifications", description = "The fel orcs of Hellfire Citadel must be scoured from our birthland!  To attack them, we must first secure forward staging points near the Citadel.\n\nOur outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them!\n\nWe want you to stop the Alliance and capture these forts.  Aid in the capture of each fort and then return to me.\n\nFor the Horde!", sourceObjective = "Capture the Overlook, the Stadium and Broken Hill, then return to Battlecryer Blackeye in Thrallmar.", progress = "Return to me after you have helped capture each fort!", completion = "Nice work, {name}.  I could almost hear the battles waged at those forts.  I wish I was there to see them!", sourceObjectiveStatus = "unverified-source-field" }
quests[13410] = { id = 13410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hellfire Fortifications", description = "The Hellfire Citadel wages constant battles with our forces.  We are holding our own so far, but we can't yet launch a real offensive against them.  To do that, we need forward staging areas.\n\nOur scouts identified three fortifications near Hellfire Citadel.  We want you to help secure these forts.  Capture each fort, and then report back to me.\n\nMay fortune shine upon you in the conflicts ahead, {name}, for you will no doubt clash with Horde forces eager to gain these same fortifications.", sourceObjective = "Capture the Overlook, the Stadium and Broken Hill, then return to Warrant Officer Tracy Proudwell in Honor Hold in Hellfire Peninsula.", completion = "Well done, {name}.  Your actions in the field are instrumental in our battle for Hellfire Peninsula.", sourceObjectiveStatus = "unverified-source-field" }
